/**
 * @file apps/fmd-desktop/src/actions/vaultActions.ts
 *
 * Zweck:
 * - Uebernimmt Vault-bezogene Aktionen fuer die Keybinding-Registry.
 */

type VaultActionHandlers = {
  handleRescanVault: (source?: string) => Promise<boolean>;
};

export const refreshActiveVault = async (
  actions: VaultActionHandlers,
  source = "unknown",
) => {
  if (import.meta.env.DEV) {
    console.info("[vault] Refresh trigger received", { source });
  }
  try {
    const success = await actions.handleRescanVault(source);
    if (!success && import.meta.env.DEV) {
      console.warn("[vault] Refresh request failed", { source });
    }
    return success;
  } catch (error) {
    if (import.meta.env.DEV) {
      console.error("[vault] Refresh crashed", { source, error });
    }
    return false;
  }
};

/*
 * @file apps/fmd-desktop/src/App.css
 *
 * Zweck:
 * - Bietet den zentralen Stylesheet-Entry fuer das Frontend.
 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer App.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/styles/tokens.css: Styles.
 * - apps/fmd-desktop/src/styles/base.css: Styles.
 * - apps/fmd-desktop/src/styles/layout.css: Styles.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

@import "./styles/tokens.css";
@import "./styles/base.css";
@import "./styles/layout.css";
@import "./styles/components/buttons.css";
@import "./styles/components/content.css";
@import "./styles/components/panels.css";
@import "./styles/components/flashcards.css";
@import "./styles/components/stats.css";
@import "./styles/components/help.css";
@import "./styles/components/spaced-repetition.css";
@import "./styles/components/panel-layout.css";
@import "./styles/components/modals.css";
@import "./styles/components/vault-manager.css";
@import "./styles/components/preview.css";
@import "./styles/components/exam-editor.css";
@import "./styles/components/utility.css";
@import "./styles/components/settings.css";
@import "./styles/components/responsive.css";

/**
 * @file apps/fmd-desktop/src/App.tsx
 *
 * Zweck:
 * - Rendert die App-Shell und routet zwischen Hauptseiten.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/components/AppStateProvider.tsx: UI-Komponente.
 * - apps/fmd-desktop/src/components/AppErrorBoundary.tsx: UI-Komponente.
 * - apps/fmd-desktop/src/components/SidebarNav.tsx: UI-Komponente.
 *
 * Exportiert:
 * - App: React-Komponente.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import "./App.css";
import { AppStateProvider, useAppState } from "./components/AppStateProvider";
import { AppErrorBoundary } from "./components/AppErrorBoundary";
import { ModalShell } from "./components/ModalShell";
import { NoteModal } from "./components/NoteModal";
import { NoteFilesPanel } from "./components/NoteFilesPanel";
import { SidebarNav } from "./components/SidebarNav";
import { StudySectionNav } from "./components/StudySectionNav";
import {
  UserVaultCustomPathModal,
  UserVaultProfileModal,
  UserVaultSyncProviderModal,
} from "./components/UserVaultGateModals";
import { LayoutModeProvider, useLayoutMode } from "./lib/layoutMode";
import { useMediaQuery } from "./lib/useMediaQuery";
import {
  getEffectiveBinding,
  getShortcutPlatform,
  isEditableTarget,
  matchesBinding,
} from "./lib/shortcuts/bindings";
import { getActiveCloseLayer } from "./lib/shortcuts/closeOrBack";
import { getShortcutById } from "./lib/shortcuts/registry";
import { isSyncProviderEnabled, logWordPressFeatureStatus } from "./lib/featureFlags";
import { registerGlobalShortcuts } from "./keybindings/registerGlobalShortcuts";
import { subscribeSettingsFocus } from "./features/settings/settingsDeepLink";
import { DashboardPage, type DashboardPageHandle, type DashboardView } from "./pages/DashboardPage";
import { ExamSimulationPage } from "./pages/ExamSimulationPage";
import { FlashcardPage } from "./pages/FlashcardPage";
import { FastFlashcardPage } from "./pages/FastFlashcardPage";
import { HelpPage } from "./pages/HelpPage";
import { SettingsPage } from "./pages/SettingsPage";
import { SpacedRepetitionPage } from "./pages/SpacedRepetitionPage";
import { DEFAULT_HELP_TOPIC_ID } from "./pages/help/helpContent";
import type { StudySectionKey } from "./lib/studySections";

type WalletGateId = "custom-path" | "profile" | "sync-provider";

const AppContent = () => {
  const {
    actions,
    flashcards,
    fastFlashcards,
    help,
    preview,
    settings,
    settingsNav,
    spacedRepetition,
    userVault,
    vault,
  } = useAppState();
  const [activeTab, setActiveTab] = useState<StudySectionKey>("dashboard");
  const [isMobileNavOpen, setIsMobileNavOpen] = useState(false);
  const [dashboardView, setDashboardView] = useState<DashboardView>("markdown");
  const [isNoteModalOpen, setIsNoteModalOpen] = useState(false);
  const [noteDialogSection, setNoteDialogSection] = useState<StudySectionKey | null>(
    null,
  );
  const dashboardRef = useRef<DashboardPageHandle | null>(null);
  const noteButtonRef = useRef<HTMLButtonElement | null>(null);
  const noteWasOpenRef = useRef(false);
  const prevTabRef = useRef<StudySectionKey>(activeTab);
  const prevDashboardViewRef = useRef<DashboardView>(dashboardView);
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [openGateId, setOpenGateId] = useState<WalletGateId | null>(null);
  const [dismissedGateId, setDismissedGateId] = useState<WalletGateId | null>(null);
  const isDashboard = activeTab === "dashboard";
  const platform = getShortcutPlatform();
  const layoutMode = useLayoutMode();
  const showStudySectionNav = layoutMode === "table";
  const isToolbarCollapsed = layoutMode === "table";
  const isNoteViewport = useMediaQuery("(max-width: 980px)", false);
  const isDashboardNoteEligible =
    activeTab === "dashboard" &&
    (dashboardView === "markdown" || dashboardView === "exam") &&
    isNoteViewport;
  const isSectionNoteEligible = isNoteViewport && activeTab !== "dashboard";
  const isNoteModalEligible = isDashboardNoteEligible || isSectionNoteEligible;
  const closeCommand = useMemo(() => getShortcutById("uiCloseOrBack"), []);
  const closeBinding = useMemo(
    () =>
      closeCommand
        ? getEffectiveBinding(closeCommand, settings.keyboardShortcuts.bindings, platform)
        : null,
    [closeCommand, platform, settings.keyboardShortcuts.bindings],
  );
  const activeProfileName = userVault.activeProfile?.name?.trim() ?? "";
  const isWalletOpen = Boolean(vault.vaultPath);
  const isUserVaultReady = userVault.status !== "loading";
  const isActivePathReady = Boolean(userVault.resolvedPath);
  const isProfileReady = Boolean(userVault.activeProfileId && activeProfileName);
  const syncProviderEnabled = isSyncProviderEnabled();
  const syncProviderRequired = false; // TODO: enable when product rule requires sync setup.
  const syncProviderConfigured = false; // TODO: wire to persisted sync provider config.
  const shouldGateSyncProvider =
    syncProviderEnabled && syncProviderRequired && !syncProviderConfigured;
  const nextGate: WalletGateId | null = !isWalletOpen || !isUserVaultReady
    ? null
    : !isActivePathReady
      ? "custom-path"
      : !isProfileReady
        ? "profile"
        : shouldGateSyncProvider
          ? "sync-provider"
          : null;
  const showInlineGate = Boolean(nextGate) && !openGateId;
  const gateCopy = nextGate
    ? {
        "custom-path": {
          eyebrow: "Active path required",
          title: "Set an active path to continue",
          description:
            "Choose where your profile data is stored. Pick a custom folder if you prefer.",
          cta: "Set active path",
        },
        profile: {
          eyebrow: "Profile required",
          title: "Create a profile to continue",
          description:
            "Your progress is stored per profile. Create or load a profile to continue working in this vault.",
          cta: "Create profile",
        },
        "sync-provider": {
          eyebrow: "Sync provider",
          title: "Configure sync provider",
          description: "Set up a sync provider to continue.",
          cta: "Configure sync",
        },
      }[nextGate]
    : null;
  const requestDashboardViewChange = useCallback(
    (nextView: DashboardView) => {
      if (activeTab === "dashboard" && dashboardRef.current) {
        dashboardRef.current.requestVaultViewChange(nextView);
        return;
      }
      setDashboardView(nextView);
    },
    [activeTab],
  );
  const handleTabChange = useCallback(
    (tab: StudySectionKey) => {
      setActiveTab(tab);
      setIsMobileNavOpen(false);
    },
    [setActiveTab, setIsMobileNavOpen],
  );
  const handleStudySectionSelect = useCallback(
    (tab: StudySectionKey) => {
      if (tab === "dashboard") {
        const nextView: DashboardView =
          dashboardView === "markdown" ? "exam" : "markdown";
        requestDashboardViewChange(nextView);
        handleTabChange("dashboard");
        return;
      }
      handleTabChange(tab);
      if (tab === "flashcard" && !flashcards.isFlashcardScanning) {
        void flashcards.handleFlashcardScan();
      } else if (tab === "fast-flashcard" && !fastFlashcards.isFlashcardScanning) {
        void fastFlashcards.handleFlashcardScan();
      } else if (
        tab === "spaced-repetition" &&
        !flashcards.isFlashcardScanning &&
        spacedRepetition.spacedRepetitionActiveUser
      ) {
        void spacedRepetition.handleSpacedRepetitionActiveUserLoadCards();
      }
    },
    [
      dashboardView,
      flashcards,
      fastFlashcards,
      handleTabChange,
      requestDashboardViewChange,
      spacedRepetition,
    ],
  );

  const handleGateClose = useCallback(() => {
    setDismissedGateId((prev) => openGateId ?? prev);
    setOpenGateId(null);
  }, [openGateId]);

  const handleGateOpen = useCallback(() => {
    if (!nextGate) {
      return;
    }
    setDismissedGateId(null);
    setOpenGateId(nextGate);
  }, [nextGate]);

  const handleNoteModalOpen = useCallback(() => {
    if (!isNoteModalEligible) {
      return;
    }
    setNoteDialogSection(activeTab);
    setIsNoteModalOpen(true);
  }, [activeTab, isNoteModalEligible]);

  const handleNoteModalClose = useCallback(() => {
    setIsNoteModalOpen(false);
    setNoteDialogSection(null);
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented) {
        return;
      }
      if (!closeCommand || !closeBinding) {
        return;
      }
      if (!closeCommand.allowInTextInputs && isEditableTarget(event.target)) {
        return;
      }
      if (!matchesBinding(event, closeBinding)) {
        return;
      }
      const layer = getActiveCloseLayer();
      if (!layer) {
        return;
      }
      event.preventDefault();
      layer.onClose();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [closeBinding, closeCommand]);

  useEffect(() => {
    if (!isNoteModalOpen) {
      return;
    }
    if (!isNoteModalEligible) {
      setIsNoteModalOpen(false);
      setNoteDialogSection(null);
    }
  }, [isNoteModalEligible, isNoteModalOpen]);

  useEffect(() => {
    if (!isNoteModalOpen) {
      prevTabRef.current = activeTab;
      prevDashboardViewRef.current = dashboardView;
      return;
    }
    const tabChanged = prevTabRef.current !== activeTab;
    const viewChanged = prevDashboardViewRef.current !== dashboardView;
    if (tabChanged || viewChanged) {
      setIsNoteModalOpen(false);
      setNoteDialogSection(null);
    }
    prevTabRef.current = activeTab;
    prevDashboardViewRef.current = dashboardView;
  }, [activeTab, dashboardView, isNoteModalOpen]);

  useEffect(() => {
    if (noteWasOpenRef.current && !isNoteModalOpen) {
      noteButtonRef.current?.focus();
    }
    noteWasOpenRef.current = isNoteModalOpen;
  }, [isNoteModalOpen]);

  const noteFilesDialogOpen = Boolean(
    isNoteModalOpen && noteDialogSection && noteDialogSection !== "dashboard",
  );
  const useFastNoteFiles = noteDialogSection === "fast-flashcard";
  const noteFilesSource = useFastNoteFiles ? fastFlashcards : flashcards;
  const noteFilesListState = noteFilesSource.isFlashcardScanning ? "loading" : "idle";

  useEffect(() => {
    if (!nextGate) {
      setOpenGateId(null);
      setDismissedGateId(null);
      return;
    }
    if (dismissedGateId === nextGate) {
      setOpenGateId(null);
      return;
    }
    setOpenGateId(nextGate);
  }, [dismissedGateId, nextGate]);

  useEffect(() => {
    logWordPressFeatureStatus();
  }, []);

  const handleOpenHelp = useCallback(() => {
    help.setActiveTopicId(DEFAULT_HELP_TOPIC_ID);
    setIsHelpOpen(true);
    setIsSettingsOpen(false);
  }, [help]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
    setIsHelpOpen(false);
  }, []);

  const handleCloseHelp = useCallback(() => {
    setIsHelpOpen(false);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  useEffect(() => {
    return subscribeSettingsFocus((request) => {
      settingsNav.setActiveSettingsPage(request.pageId);
      setIsSettingsOpen(true);
      setIsHelpOpen(false);
    });
  }, [settingsNav, setIsHelpOpen, setIsSettingsOpen]);

  useEffect(() => {
    const dispose = registerGlobalShortcuts({
      bindings: settings.keyboardShortcuts.bindings,
      platform,
      context: {
        actions: {
          handleRescanVault: actions.handleRescanVault,
        },
      },
    });
    return dispose;
  }, [
    actions.handleRescanVault,
    platform,
    settings.keyboardShortcuts.bindings,
  ]);

  return (
    <div
      className={`app-shell layout-${layoutMode} ${
        showStudySectionNav ? "compact-top-nav" : ""
      } ${isToolbarCollapsed ? "sidebar-collapsed" : ""} ${
        isDashboard ? "dashboard-active" : ""
      } ${
        isMobileNavOpen ? "nav-open" : ""
      }`}
      data-study-subview={dashboardView}
    >
      {showStudySectionNav ? (
        <StudySectionNav
          activeTab={activeTab}
          onSectionSelect={handleStudySectionSelect}
          isMobileNavOpen={isMobileNavOpen}
          onMobileNavOpen={() => setIsMobileNavOpen(true)}
          showNoteAction={isNoteModalEligible}
          onNoteAction={handleNoteModalOpen}
          noteActionRef={noteButtonRef}
          isNoteActionActive={isNoteModalOpen}
        />
      ) : null}
      <SidebarNav
        activeTab={activeTab}
        onTabChange={handleTabChange}
        vaultView={dashboardView}
        onVaultViewChange={requestDashboardViewChange}
        onOpenHelp={handleOpenHelp}
        onOpenSettings={handleOpenSettings}
        onMobileNavClose={() => setIsMobileNavOpen(false)}
      />
      <main className="content">
        <div className="mobile-nav-header">
          {!showStudySectionNav ? (
            <button
              type="button"
              className="ghost small mobile-nav-toggle"
              onClick={() => setIsMobileNavOpen(true)}
              aria-label="Open navigation"
              aria-controls="app-sidebar"
              aria-expanded={isMobileNavOpen}
            >
              Menu
            </button>
          ) : null}
          <div id="mobile-nav-actions" className="mobile-nav-actions" />
        </div>
        {activeTab !== "dashboard" && showInlineGate && gateCopy ? (
          <section className="panel">
            <div className="panel-header">
              <div className="panel-header-content">
                <span className="eyebrow">{gateCopy.eyebrow}</span>
                <h3>{gateCopy.title}</h3>
                <p className="muted">{gateCopy.description}</p>
              </div>
              <button type="button" className="primary" onClick={handleGateOpen}>
                {gateCopy.cta}
              </button>
            </div>
          </section>
        ) : null}
        {activeTab === "dashboard" ? (
          <DashboardPage
            ref={dashboardRef}
            initialVaultView={dashboardView}
            onVaultViewChange={setDashboardView}
            isNoteModalOpen={isNoteModalOpen}
            noteModalEnabled={isNoteModalEligible}
            onNoteModalClose={handleNoteModalClose}
            showGate={showInlineGate}
            gateEyebrow={gateCopy?.eyebrow}
            gateTitle={gateCopy?.title}
            gateDescription={gateCopy?.description}
            gateCtaLabel={gateCopy?.cta}
            onOpenGate={handleGateOpen}
          />
        ) : activeTab === "exam" ? (
          <ExamSimulationPage />
        ) : activeTab === "flashcard" ? (
          <FlashcardPage onSectionSelect={handleStudySectionSelect} />
        ) : activeTab === "spaced-repetition" ? (
          <SpacedRepetitionPage onSectionSelect={handleStudySectionSelect} />
        ) : (
          <FastFlashcardPage onSectionSelect={handleStudySectionSelect} />
        )}
      </main>
      <NoteModal isOpen={noteFilesDialogOpen} onClose={handleNoteModalClose} title="Note">
        <NoteFilesPanel
          files={noteFilesSource.flashcardFiles}
          listState={noteFilesListState}
          listError={noteFilesSource.flashcardFilesError}
          selectedFile={preview.selectedFile}
          vaultPath={vault.vaultPath}
          onSelectFile={actions.handleSelectFile}
        />
      </NoteModal>
      <ModalShell isOpen={isHelpOpen} title="Help" onClose={handleCloseHelp}>
        <div className="hub-modal-scroll">
          <HelpPage onCloseHelp={handleCloseHelp} />
        </div>
      </ModalShell>
      <ModalShell isOpen={isSettingsOpen} title="Settings" onClose={handleCloseSettings}>
        <div className="hub-modal-scroll">
          <SettingsPage />
        </div>
      </ModalShell>
      <UserVaultCustomPathModal
        isOpen={openGateId === "custom-path"}
        onClose={handleGateClose}
        userVault={userVault}
      />
      <UserVaultProfileModal
        isOpen={openGateId === "profile"}
        onClose={handleGateClose}
        userVault={userVault}
      />
      <UserVaultSyncProviderModal
        isOpen={openGateId === "sync-provider"}
        onClose={handleGateClose}
        userVault={userVault}
      />
      <button
        type="button"
        className="mobile-nav-backdrop"
        onClick={() => setIsMobileNavOpen(false)}
        aria-hidden={!isMobileNavOpen}
        tabIndex={-1}
      />
    </div>
  );
};

function App() {
  return (
    <AppErrorBoundary>
      <AppStateProvider>
        <LayoutModeProvider>
          <AppContent />
        </LayoutModeProvider>
      </AppStateProvider>
    </AppErrorBoundary>
  );
}

export default App;

/**
 * @file apps/fmd-desktop/src/components/AppErrorBoundary.tsx
 *
 * Zweck:
 * - Rendert die UI-Komponente App Error Boundary.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.tsx: Nutzt dieses Modul.
 * - react: React-API.
 *
 * Exportiert:
 * - AppErrorBoundary: React-Komponente.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import { Component, type ErrorInfo, type ReactNode } from "react";

type AppErrorBoundaryProps = {
  children: ReactNode;
};

type AppErrorBoundaryState = {
  error: Error | null;
  errorInfo: ErrorInfo | null;
};

const isDev = import.meta.env.DEV;

export class AppErrorBoundary extends Component<
  AppErrorBoundaryProps,
  AppErrorBoundaryState
> {
  state: AppErrorBoundaryState = {
    error: null,
    errorInfo: null,
  };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("App crashed during render", error, errorInfo);
    this.setState({ errorInfo });
  }

  render() {
    const { error, errorInfo } = this.state;
    if (!error) {
      return this.props.children;
    }

    const stack =
      (error && error.stack ? error.stack : "") ||
      (errorInfo?.componentStack ? errorInfo.componentStack : "");

    return (
      <div
        style={{
          minHeight: "100vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "32px",
          background: "#F7F5F2",
          color: "#1B1B1B",
          fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace",
        }}
      >
        <div style={{ maxWidth: 760, width: "100%" }}>
          <h1 style={{ marginBottom: 12, fontSize: 20 }}>
            App failed to render
          </h1>
          <p style={{ marginBottom: 16 }}>
            An unexpected error occurred during startup. Check the console for
            details.
          </p>
          <div
            style={{
              padding: "12px 16px",
              border: "1px solid #E0DCD4",
              borderRadius: 8,
              background: "#FFFFFF",
              wordBreak: "break-word",
              marginBottom: isDev && stack ? 16 : 0,
            }}
          >
            {error.message || String(error)}
          </div>
          {isDev && stack ? (
            <pre
              style={{
                whiteSpace: "pre-wrap",
                background: "#111827",
                color: "#F9FAFB",
                padding: "12px 16px",
                borderRadius: 8,
                fontSize: 12,
                lineHeight: 1.5,
              }}
            >
              {stack.trim()}
            </pre>
          ) : null}
        </div>
      </div>
    );
  }
}

/**
 * @file apps/fmd-desktop/src/components/AppStateProvider.tsx
 *
 * Zweck:
 * - Rendert die UI-Komponente App State Provider.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/lib/color.ts: Hilfsfunktionen oder Typen.
 * - apps/fmd-desktop/src/lib/path.ts: Hilfsfunktionen oder Typen.
 * - apps/fmd-desktop/src/lib/theme.ts: Typen.
 *
 * Exportiert:
 * - AppStateProvider: React-Komponente.
 * - useAppState: Hook fuer /.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { isValidHex, normalizeHex } from "../lib/color";
import { isHiddenPath, normalizeRelativePath, normalizeVaultPath } from "../lib/path";
import { type ThemeMode } from "../lib/theme";
import { type VaultFile } from "../lib/tree";
import { useFlashcards } from "../features/flashcards/useFlashcards";
import { usePreview } from "../features/preview/usePreview";
import { useAppSettings } from "../features/settings/useAppSettings";
import { type SettingsPageId } from "../features/settings/settingsNavigation";
import { useSpacedRepetition } from "../features/spaced-repetition/useSpacedRepetition";
import { useUserVault } from "../features/user-vault/useUserVault";
import { useVault } from "../features/vault/useVault";
import { LargeVaultWarningModal } from "./LargeVaultWarningModal";
import { VaultManagerModal } from "./VaultManagerModal";
import { DEFAULT_HELP_TOPIC_ID } from "../pages/help/helpContent";

type AppActions = {
  handlePickVault: () => Promise<boolean>;
  handleSwitchVault: (path: string) => Promise<boolean>;
  handleRemoveRecentVault: (path: string) => void;
  handleOpenVaultManager: () => void;
  handleClearVault: () => void;
  handleSelectFile: (file: VaultFile) => void;
  handleThemeChange: (nextTheme: ThemeMode) => void;
  handleAccentPick: (value: string) => void;
  handleAccentInputChange: (value: string) => void;
  handleCopyAccent: () => Promise<void>;
  handleCopyVaultPath: () => Promise<void>;
  handleRescanVault: (source?: string) => Promise<boolean>;
  handleResetIndex: () => void;
  handleMaxFilesPerScanChange: (value: string) => void;
};

type AppState = {
  actions: AppActions;
  flashcards: ReturnType<typeof useFlashcards>;
  fastFlashcards: ReturnType<typeof useFlashcards>;
  help: {
    activeTopicId: string;
    setActiveTopicId: (value: string) => void;
  };
  settingsNav: {
    activeSettingsPage: SettingsPageId;
    setActiveSettingsPage: (value: SettingsPageId) => void;
  };
  preview: ReturnType<typeof usePreview>;
  settings: ReturnType<typeof useAppSettings>;
  spacedRepetition: ReturnType<typeof useSpacedRepetition>;
  userVault: ReturnType<typeof useUserVault>;
  vault: ReturnType<typeof useVault> & {
    activeFolderPath: string | null;
    setActiveFolderPath: (value: string | null) => void;
  };
};

const AppStateContext = createContext<AppState | null>(null);

const countMarkdownFiles = (files: VaultFile[], showHiddenFolders: boolean) =>
  files.reduce((count, file) => {
    const relativePath = normalizeRelativePath(file.relative_path);
    if (!showHiddenFolders && isHiddenPath(relativePath)) {
      return count;
    }
    if (relativePath.toLowerCase().endsWith(".md")) {
      return count + 1;
    }
    return count;
  }, 0);

const parseVaultWarningThreshold = (value: string) => {
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  const parsed = Number.parseInt(trimmed, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const MAX_RECENT_VAULTS = 10;

export const AppStateProvider = ({ children }: { children: ReactNode }) => {
  const settings = useAppSettings();
  const [activeHelpTopicId, setActiveHelpTopicId] = useState<string>(
    DEFAULT_HELP_TOPIC_ID,
  );
  const [activeFolderPath, setActiveFolderPathState] = useState<string | null>(
    null,
  );
  const [largeVaultWarningCount, setLargeVaultWarningCount] = useState<
    number | null
  >(null);
  const [isVaultManagerOpen, setIsVaultManagerOpen] = useState(false);
  const [activeSettingsPage, setActiveSettingsPage] =
    useState<SettingsPageId>("appearance");
  const {
    activeNotePath,
    accentColor,
    persistSettings,
    setAccentColor,
    setAccentDraft,
    setAccentError,
    setActiveNotePath,
    showHiddenFolders,
    maxFilesPerScan,
    setMaxFilesPerScan,
    setTheme,
    settingsLoaded,
    vaultPath: storedVaultPath,
    recentVaults,
    flashcardMode,
    flashcardOrder,
    flashcardPageSize,
    flashcardScope,
    setFlashcardMode,
    setFlashcardOrder,
    setFlashcardPageSize,
    setFlashcardScope,
    fastFlashcardMode,
    fastFlashcardOrder,
    fastFlashcardScope,
    setFastFlashcardMode,
    setFastFlashcardOrder,
    setFastFlashcardScope,
    setSolutionRevealEnabled,
    setStatsResetMode,
    setUserVaultProfileContext,
    solutionRevealEnabled,
    statsResetMode,
  } = settings;
  const vault = useVault({ persistSettings, showHiddenFolders });
  const userVault = useUserVault({
    vaultPath: vault.vaultPath,
    mode: settings.userVaultMode,
    setMode: settings.setUserVaultMode,
    customPath: settings.userVaultCustomPath,
    setCustomPath: settings.setUserVaultCustomPath,
  });
  useEffect(() => {
    setUserVaultProfileContext(userVault.activeProfilePath, userVault.revision);
  }, [setUserVaultProfileContext, userVault.activeProfilePath, userVault.revision]);
  const preview = usePreview();
  const flashcards = useFlashcards({
    files: vault.files,
    preview: preview.preview,
    selectedFile: preview.selectedFile,
    vaultPath: vault.vaultPath,
    settings: {
      flashcardMode,
      flashcardOrder,
      flashcardPageSize,
      flashcardScope,
      setFlashcardMode,
      setFlashcardOrder,
      setFlashcardPageSize,
      setFlashcardScope,
      setSolutionRevealEnabled,
      setStatsResetMode,
      solutionRevealEnabled,
      statsResetMode,
    },
  });
  const fastFlashcards = useFlashcards({
    files: vault.files,
    preview: preview.preview,
    selectedFile: preview.selectedFile,
    vaultPath: vault.vaultPath,
    settings: {
      flashcardMode: fastFlashcardMode,
      flashcardOrder: fastFlashcardOrder,
      flashcardPageSize,
      flashcardScope: fastFlashcardScope,
      setFlashcardMode: setFastFlashcardMode,
      setFlashcardOrder: setFastFlashcardOrder,
      setFlashcardPageSize,
      setFlashcardScope: setFastFlashcardScope,
      setSolutionRevealEnabled,
      setStatsResetMode,
      solutionRevealEnabled,
      statsResetMode,
    },
  });
  const spacedRepetition = useSpacedRepetition({
    isFlashcardScanning: flashcards.isFlashcardScanning,
    scanFlashcards: flashcards.scanFlashcards,
    setIsFlashcardScanning: flashcards.setIsFlashcardScanning,
    userVaultProfilePath: userVault.activeProfilePath,
    userVaultRevision: userVault.revision,
    vaultPath: vault.vaultPath,
    settings: {
      setSpacedRepetitionBoxes: settings.setSpacedRepetitionBoxes,
      setSpacedRepetitionOrder: settings.setSpacedRepetitionOrder,
      setSpacedRepetitionPageSize: settings.setSpacedRepetitionPageSize,
      setSpacedRepetitionRepetitionStrength:
        settings.setSpacedRepetitionRepetitionStrength,
      setSpacedRepetitionStatsView: settings.setSpacedRepetitionStatsView,
      spacedRepetitionBoxes: settings.spacedRepetitionBoxes,
      spacedRepetitionOrder: settings.spacedRepetitionOrder,
      spacedRepetitionPageSize: settings.spacedRepetitionPageSize,
      spacedRepetitionRepetitionStrength:
        settings.spacedRepetitionRepetitionStrength,
      spacedRepetitionStatsView: settings.spacedRepetitionStatsView,
    },
  });
  const hasRestoredVault = useRef(false);
  const lastRecentVaultRef = useRef<string | null>(null);
  const isRestoringActiveNote = useRef(false);
  const hasResolvedActiveNote = useRef(false);
  const {
    loadVault,
    pickVault,
    rescanVault,
    restoreSnapshot: restoreVaultSnapshot,
    listState,
    setFiles,
    setListError,
    setLastRefreshAt,
    setListState,
    setVaultPath,
    takeSnapshot: takeVaultSnapshot,
    vaultPath,
  } = vault;
  const {
    resetPreview,
    restoreSnapshot: restorePreviewSnapshot,
    selectFile,
    setPreviewError,
    takeSnapshot: takePreviewSnapshot,
  } = preview;
  const {
    resetFlashcards,
    restoreSnapshot: restoreFlashcardsSnapshot,
    takeSnapshot: takeFlashcardsSnapshot,
  } = flashcards;
  const { resetFlashcards: resetFastFlashcards } = fastFlashcards;

  const setActiveFolderPath = useCallback((value: string | null) => {
    if (value === null) {
      setActiveFolderPathState(null);
      return;
    }
    const normalized = normalizeRelativePath(value).replace(/\/+$/, "");
    setActiveFolderPathState(normalized);
  }, []);

  useEffect(() => {
    setActiveFolderPath(null);
  }, [setActiveFolderPath, vault.vaultPath]);

  useEffect(() => {
    if (!settingsLoaded || hasRestoredVault.current) {
      return;
    }
    hasRestoredVault.current = true;
    if (!storedVaultPath) {
      return;
    }
    let cancelled = false;

    const restoreVault = async () => {
      const results = await loadVault(storedVaultPath, {
        persist: false,
        clearOnFailure: false,
        errorMessage:
          "Saved vault is unavailable. Please reselect.",
      });
      if (!results && !cancelled) {
        setVaultPath(null);
        await persistSettings({ vaultPath: null });
      }
    };

    void restoreVault();

    return () => {
      cancelled = true;
    };
  }, [loadVault, persistSettings, setVaultPath, settingsLoaded, storedVaultPath]);

  useEffect(() => {
    if (!settingsLoaded) {
      return;
    }
    if (preview.selectedFile && !hasResolvedActiveNote.current) {
      hasResolvedActiveNote.current = true;
    }
    if (!hasResolvedActiveNote.current) {
      return;
    }
    const nextPath = preview.selectedFile?.relative_path ?? null;
    if (nextPath === activeNotePath) {
      return;
    }
    setActiveNotePath(nextPath);
  }, [activeNotePath, preview.selectedFile, setActiveNotePath, settingsLoaded]);

  useEffect(() => {
    if (!settingsLoaded) {
      return;
    }
    if (!vault.vaultPath || vault.listState !== "idle") {
      return;
    }
    if (preview.selectedFile || isRestoringActiveNote.current) {
      if (preview.selectedFile) {
        hasResolvedActiveNote.current = true;
      }
      return;
    }
    if (!activeNotePath) {
      hasResolvedActiveNote.current = true;
      return;
    }
    const storedFile = vault.files.find(
      (file) =>
        file.relative_path === activeNotePath || file.path === activeNotePath,
    );
    if (!storedFile) {
      setActiveNotePath(null);
      if (vault.files.length === 0) {
        hasResolvedActiveNote.current = true;
        return;
      }
    }
    const nextFile = storedFile ?? vault.files[0];
    if (!nextFile) {
      return;
    }
    isRestoringActiveNote.current = true;
    resetFlashcards();
    void Promise.resolve(selectFile(nextFile)).finally(() => {
      isRestoringActiveNote.current = false;
      hasResolvedActiveNote.current = true;
    });
  }, [
    activeNotePath,
    preview.selectedFile,
    resetFlashcards,
    selectFile,
    setActiveNotePath,
    settingsLoaded,
    vault.files,
    vault.listState,
    vault.vaultPath,
  ]);

  const handlePickVault = useCallback(async () => {
    setPreviewError("");
    const previewSnapshot = takePreviewSnapshot();
    const flashcardsSnapshot = takeFlashcardsSnapshot();

    const results = await pickVault({
      errorMessage: "Ausgewaehlter Vault ist nicht verfuegbar.",
      onBeforeLoad: () => {
        resetPreview();
        resetFlashcards();
      },
      onLoadFailed: () => {
        restorePreviewSnapshot(previewSnapshot);
        restoreFlashcardsSnapshot(flashcardsSnapshot);
      },
    });

    if (results) {
      const count = countMarkdownFiles(results.files, showHiddenFolders);
      const threshold = parseVaultWarningThreshold(maxFilesPerScan);
      if (threshold && count > threshold) {
        setLargeVaultWarningCount(count);
      } else {
        setLargeVaultWarningCount(null);
      }
    }

    return Boolean(results);
  }, [
    pickVault,
    resetFlashcards,
    resetPreview,
    restoreFlashcardsSnapshot,
    restorePreviewSnapshot,
    setPreviewError,
    takeFlashcardsSnapshot,
    takePreviewSnapshot,
    setLargeVaultWarningCount,
    maxFilesPerScan,
    showHiddenFolders,
  ]);

  const handleSwitchVault = useCallback(
    async (path: string) => {
      if (!path) {
        return false;
      }
      setPreviewError("");
      const previewSnapshot = takePreviewSnapshot();
      const flashcardsSnapshot = takeFlashcardsSnapshot();
      const vaultSnapshot = takeVaultSnapshot();

      resetPreview();
      resetFlashcards();

      const errorMessage = "Ausgewaehlter Vault ist nicht verfuegbar.";
      const results = await loadVault(path, {
        persist: true,
        clearOnFailure: false,
        errorMessage,
      });

      if (!results) {
        restoreVaultSnapshot(vaultSnapshot);
        setListError(errorMessage);
        restorePreviewSnapshot(previewSnapshot);
        restoreFlashcardsSnapshot(flashcardsSnapshot);
        return false;
      }

      const count = countMarkdownFiles(results.files, showHiddenFolders);
      const threshold = parseVaultWarningThreshold(maxFilesPerScan);
      if (threshold && count > threshold) {
        setLargeVaultWarningCount(count);
      } else {
        setLargeVaultWarningCount(null);
      }

      return true;
    },
    [
      loadVault,
      maxFilesPerScan,
      resetFlashcards,
      resetPreview,
      restoreFlashcardsSnapshot,
      restorePreviewSnapshot,
      restoreVaultSnapshot,
      setLargeVaultWarningCount,
      setListError,
      setPreviewError,
      showHiddenFolders,
      takeFlashcardsSnapshot,
      takePreviewSnapshot,
      takeVaultSnapshot,
    ],
  );

  const updateRecentVaults = useCallback(
    async (path: string) => {
      if (!settingsLoaded) {
        return;
      }
      const normalized = normalizeVaultPath(path);
      if (!normalized) {
        return;
      }
      const next = [
        { path, lastOpenedAt: new Date().toISOString() },
        ...recentVaults.filter(
          (entry) => normalizeVaultPath(entry.path) !== normalized,
        ),
      ].slice(0, MAX_RECENT_VAULTS);
      await persistSettings({ recentVaults: next });
    },
    [persistSettings, recentVaults, settingsLoaded],
  );

  const handleRemoveRecentVault = useCallback(
    (path: string) => {
      const normalized = normalizeVaultPath(path);
      if (!normalized) {
        return;
      }
      if (lastRecentVaultRef.current === normalized) {
        lastRecentVaultRef.current = null;
      }
      const next = recentVaults.filter(
        (entry) => normalizeVaultPath(entry.path) !== normalized,
      );
      if (next.length === recentVaults.length) {
        return;
      }
      void persistSettings({ recentVaults: next });
    },
    [persistSettings, recentVaults],
  );

  useEffect(() => {
    if (!settingsLoaded) {
      return;
    }
    if (!vault.vaultPath) {
      lastRecentVaultRef.current = null;
      return;
    }
    if (vault.listState !== "idle") {
      return;
    }
    const normalized = normalizeVaultPath(vault.vaultPath);
    if (!normalized) {
      return;
    }
    if (lastRecentVaultRef.current === normalized) {
      return;
    }
    lastRecentVaultRef.current = normalized;
    void updateRecentVaults(vault.vaultPath);
  }, [settingsLoaded, updateRecentVaults, vault.listState, vault.vaultPath]);

  const handleOpenVaultManager = useCallback(() => {
    setIsVaultManagerOpen(true);
  }, []);

  const handleCloseVaultManager = useCallback(() => {
    setIsVaultManagerOpen(false);
  }, []);

  const handleSelectFile = useCallback(
    (file: VaultFile) => {
      resetFlashcards();
      void selectFile(file);
    },
    [resetFlashcards, selectFile],
  );

  const handleThemeChange = useCallback(
    (nextTheme: ThemeMode) => {
      setTheme(nextTheme);
    },
    [setTheme],
  );

  const handleAccentPick = useCallback(
    (value: string) => {
      const normalized = normalizeHex(value);
      if (!isValidHex(normalized)) {
        return;
      }
      setAccentError("");
      setAccentColor(normalized);
      setAccentDraft(normalized);
    },
    [setAccentColor, setAccentDraft, setAccentError],
  );

  const handleAccentInputChange = useCallback(
    (value: string) => {
      const nextValue = normalizeHex(value);
      setAccentDraft(nextValue);
      if (!nextValue) {
        setAccentError("");
        return;
      }
      if (isValidHex(nextValue)) {
        setAccentError("");
        setAccentColor(nextValue);
      } else {
        setAccentError("HEX muss #RRGGBB sein.");
      }
    },
    [setAccentColor, setAccentDraft, setAccentError],
  );

  const handleCopyAccent = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(accentColor);
    } catch (error) {
      console.error("Failed to copy accent color", error);
    }
  }, [accentColor]);

  const handleCopyVaultPath = useCallback(async () => {
    if (!vaultPath) {
      return;
    }
    try {
      await navigator.clipboard.writeText(vaultPath);
    } catch (error) {
      console.error("Failed to copy vault path", error);
    }
  }, [vaultPath]);

  const handleRescanVault = useCallback(async (source = "unknown") => {
    if (!vaultPath) {
      setListError("Kein aktiver Vault zum Aktualisieren.");
      return false;
    }
    if (listState === "loading") {
      if (import.meta.env.DEV) {
        console.info("[vault] Refresh skipped because a scan is already running.", {
          source,
        });
      }
      return false;
    }
    if (import.meta.env.DEV) {
      console.info("[vault] Refresh requested", { vaultPath, source });
    }
    const success = await rescanVault();
    if (!success && import.meta.env.DEV) {
      console.warn("[vault] Refresh failed", { vaultPath, source });
    }
    return success;
  }, [listState, rescanVault, setListError, vaultPath]);

  const handleResetIndex = useCallback(() => {
    if (!vaultPath) {
      return;
    }
    resetPreview();
    resetFlashcards();
    resetFastFlashcards();
    setActiveFolderPath(null);
    setLargeVaultWarningCount(null);
    setFiles([]);
    setListError("");
    setListState("idle");
    setLastRefreshAt(null);
    setVaultPath(null);
    void persistSettings({ vaultPath: null, activeNotePath: null });
  }, [
    persistSettings,
    resetFastFlashcards,
    resetFlashcards,
    resetPreview,
    setActiveFolderPath,
    setFiles,
    setLargeVaultWarningCount,
    setListError,
    setListState,
    setVaultPath,
    vaultPath,
  ]);

  const handleClearVault = useCallback(() => {
    handleResetIndex();
  }, [handleResetIndex]);

  const handleMaxFilesPerScanChange = useCallback(
    (value: string) => {
      const nextValue = value.trim();
      if (nextValue === "" || /^[0-9]+$/.test(nextValue)) {
        setMaxFilesPerScan(nextValue);
      }
    },
    [setMaxFilesPerScan],
  );

  const handleLargeVaultWarningDismiss = useCallback(() => {
    setLargeVaultWarningCount(null);
  }, [setLargeVaultWarningCount]);

  const value: AppState = {
    actions: {
      handlePickVault,
      handleSwitchVault,
      handleRemoveRecentVault,
      handleOpenVaultManager,
      handleClearVault,
      handleSelectFile,
      handleThemeChange,
      handleAccentPick,
      handleAccentInputChange,
      handleCopyAccent,
      handleCopyVaultPath,
      handleRescanVault,
      handleResetIndex,
      handleMaxFilesPerScanChange,
    },
    flashcards,
    fastFlashcards,
    help: {
      activeTopicId: activeHelpTopicId,
      setActiveTopicId: setActiveHelpTopicId,
    },
    settingsNav: {
      activeSettingsPage,
      setActiveSettingsPage,
    },
    preview,
    settings,
    spacedRepetition,
    userVault,
    vault: {
      ...vault,
      activeFolderPath,
      setActiveFolderPath,
    },
  };

  return (
    <AppStateContext.Provider value={value}>
      {children}
      <VaultManagerModal
        isOpen={isVaultManagerOpen}
        vaults={recentVaults}
        activeVaultPath={vault.vaultPath}
        activeVaultError={vault.listError}
        userVault={userVault}
        onClose={handleCloseVaultManager}
        onOpenVault={handlePickVault}
        onRescanVault={handleRescanVault}
        onSwitchVault={handleSwitchVault}
        onRemoveVault={handleRemoveRecentVault}
        onClearVault={handleClearVault}
      />
      <LargeVaultWarningModal
        count={largeVaultWarningCount}
        onClose={handleLargeVaultWarningDismiss}
      />
    </AppStateContext.Provider>
  );
};

export const useAppState = () => {
  const context = useContext(AppStateContext);
  if (!context) {
    throw new Error("useAppState must be used within AppStateProvider");
  }
  return context;
};

