 */

import {
  type DragEvent,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import {
  isDragAnswerMatch,
  isInputAnswerMatch,
  type ClozeCard as ClozeCardType,
} from "../../lib/flashcards";
import {
  areClozeBlanksComplete,
  CLOZE_TOKEN_DRAG_TYPE,
  getClozeBlanks,
  isClozeCardCorrect,
  type ClozeDragPayload,
} from "../../features/flashcards/logic";
import { resolveSeed, seededShuffle } from "../../lib/seededShuffle";
import {
  CLOZE_PLACEHOLDER_PREFIX,
  CLOZE_PLACEHOLDER_SUFFIX,
  MarkdownBlocks,
} from "./MarkdownBlocks";
import { findTableLineIndices } from "../../lib/markdownTables";
import { HelpButton, hasHelpContent } from "../HelpButton";

type ClozeCardProps = {
  card: ClozeCardType;
  cardIndex: number;
  submitted: boolean;
  responses: Record<string, string>;
  submissionLocked?: boolean;
  partIndex?: number;
  showSubmit?: boolean;
  showResult?: boolean;
  revealCorrectness?: boolean;
  showSolution?: boolean;
  helpText?: string[] | string;
  helpEnabled?: boolean;
  onInputChange: (cardIndex: number, blankId: string, value: string) => void;
  onTokenDrop: (
    event: DragEvent<HTMLElement>,
    cardIndex: number,
    blankId: string,
    validTokenIds: Set<string>,
    dragBlankIds: Set<string>,
  ) => void;
  onTokenRemove: (cardIndex: number, blankId: string) => void;
  onTokenDragStart: (
    event: DragEvent<HTMLElement>,
    payload: { cardIndex: number; tokenId: string; partIndex?: number },
  ) => void;
  onBlankDragOver: (event: DragEvent<HTMLElement>) => void;
  onSubmit: (cardIndex: number, canSubmit: boolean) => void;
};

type PointerDragState = {
  pointerId: number;
  tokenId: string;
  tokenValue: string;
  sourceBlankId?: string;
  startX: number;
  startY: number;
  offsetX: number;
  offsetY: number;
  dragging: boolean;
};

type DragGhostState = {
  tokenId: string;
  tokenValue: string;
  x: number;
  y: number;
  offsetX: number;
  offsetY: number;
  sourceBlankId?: string;
};

type SelectedTokenState = {
  tokenId: string;
  tokenValue: string;
  sourceBlankId?: string;
};

const POINTER_DRAG_THRESHOLD = 8;

export const ClozeCard = ({
  card,
  cardIndex,
  submitted,
  responses,
  submissionLocked = false,
  partIndex,
  showSubmit = true,
  showResult = true,
  revealCorrectness,
  showSolution,
  helpText,
  helpEnabled,
  onBlankDragOver,
  onInputChange,
  onSubmit,
  onTokenDragStart,
  onTokenDrop,
  onTokenRemove,
}: ClozeCardProps) => {
  const cardRef = useRef<HTMLElement | null>(null);
  const pointerDragRef = useRef<PointerDragState | null>(null);
  const suppressClickRef = useRef(false);
  const [dragGhost, setDragGhost] = useState<DragGhostState | null>(null);
  const [activeDropBlankId, setActiveDropBlankId] = useState<string | null>(null);
  const [selectedToken, setSelectedToken] = useState<SelectedTokenState | null>(null);
  const blanks = getClozeBlanks(card.segments);
  const dragBlanks = blanks.filter((blank) => blank.kind === "drag");
  const dragBlankIds = new Set(dragBlanks.map((blank) => blank.id));
  const tokenById = new Map(
    card.dragTokens.map((token) => [token.id, token.value]),
  );
  const { placeholderText, blankById, blankOrderById } = useMemo(() => {
    let text = "";
    const blankMap = new Map<string, Extract<ClozeCardType["segments"][number], { type: "blank" }>>();
    const orderMap = new Map<string, number>();
    let blankIndex = 0;

    card.segments.forEach((segment) => {
      if (segment.type === "text") {
        text += segment.value;
        return;
      }
      blankMap.set(segment.id, segment);
      blankIndex += 1;
      orderMap.set(segment.id, blankIndex);
      text += `${CLOZE_PLACEHOLDER_PREFIX}${segment.id}${CLOZE_PLACEHOLDER_SUFFIX}`;
    });

    return { placeholderText: text, blankById: blankMap, blankOrderById: orderMap };
  }, [card.segments]);
  const { markdownText, questionText } = useMemo(() => {
    const trimmedQuestion = card.question.trim();
    if (!trimmedQuestion) {
      return { markdownText: placeholderText, questionText: "" };
    }
    const combinedText = `${card.question}\n${placeholderText}`;
    const combinedLines = combinedText.split("\n");
    const tableLineIndices = findTableLineIndices(combinedLines);
    const isFenceStart = /^(```|~~~)/.test(combinedLines[0]?.trimStart() ?? "");
    if (tableLineIndices.has(0) || isFenceStart) {
      return { markdownText: combinedText, questionText: "" };
    }
    return { markdownText: placeholderText, questionText: card.question };
  }, [card.question, placeholderText]);
  const normalizedPartIndex = partIndex ?? 0;
  const tokenBank = useMemo(() => {
    const identifier = `${cardIndex}:${normalizedPartIndex}:${card.question}`;
    const seed = resolveSeed(identifier);
    return seededShuffle(card.dragTokens, seed);
  }, [card.dragTokens, cardIndex, normalizedPartIndex, card.question]);
  const assignedTokenIds = new Set(
    dragBlanks
      .map((blank) => responses[blank.id])
      .filter((tokenId) => tokenById.has(tokenId)),
  );
  const hasDragTokens = tokenBank.length > 0;
  const validTokenIds = new Set(card.dragTokens.map((token) => token.id));
  const canSubmit = areClozeBlanksComplete(card, responses);
  const isCorrect = isClozeCardCorrect(card, responses);
  const reveal = revealCorrectness ?? submitted;
  const shouldShowSolution = showSolution ?? submitted;
  const resultLabel = submitted && showResult ? (isCorrect ? "Correct" : "Incorrect") : "";
  const hasHelp = helpEnabled && hasHelpContent(helpText);
  const showActions = showSubmit || (submitted && showResult) || hasHelp;

  const resolveDropBlankId = (clientX: number, clientY: number) => {
    if (typeof document === "undefined" || !document.elementsFromPoint) {
      return null;
    }
    const elements = document.elementsFromPoint(clientX, clientY);
    for (const element of elements) {
      if (!(element instanceof HTMLElement)) {
        continue;
      }
      const dropzone = element.closest<HTMLElement>('[data-dropzone="cloze-blank"]');
      if (!dropzone) {
        continue;
      }
      if (cardRef.current && !cardRef.current.contains(dropzone)) {
        continue;
      }
      const blankId = dropzone.dataset.blankId;
      if (blankId && dragBlankIds.has(blankId)) {
        return blankId;
      }
    }
    return null;
  };

  const createSyntheticDragEvent = (payload: ClozeDragPayload) => {
    const dataTransfer = {
      getData: (type: string) =>
        type === CLOZE_TOKEN_DRAG_TYPE ? JSON.stringify(payload) : "",
    };
    return {
      preventDefault: () => {},
      dataTransfer,
    } as DragEvent<HTMLElement>;
  };

  const handleTokenPointerDown = (
    event: ReactPointerEvent<HTMLButtonElement>,
    tokenId: string,
    tokenValue: string,
    sourceBlankId?: string,
  ) => {
    if (submitted) {
      return;
    }
    if (event.pointerType === "mouse") {
      return;
    }
    if (event.button !== 0) {
      return;
    }
    setSelectedToken(null);
    const rect = event.currentTarget.getBoundingClientRect();
    pointerDragRef.current = {
      pointerId: event.pointerId,
      tokenId,
      tokenValue,
      sourceBlankId,
      startX: event.clientX,
      startY: event.clientY,
      offsetX: event.clientX - rect.left,
      offsetY: event.clientY - rect.top,
      dragging: false,
    };
    setActiveDropBlankId(null);
    setDragGhost(null);
  };

  const handleTokenPointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
    const state = pointerDragRef.current;
    if (!state || event.pointerId !== state.pointerId) {
      return;
    }
    const deltaX = event.clientX - state.startX;
    const deltaY = event.clientY - state.startY;
    if (!state.dragging) {
      if (Math.hypot(deltaX, deltaY) < POINTER_DRAG_THRESHOLD) {
        return;
      }
      state.dragging = true;
      event.preventDefault();
      event.currentTarget.setPointerCapture?.(event.pointerId);
      setDragGhost({
        tokenId: state.tokenId,
        tokenValue: state.tokenValue,
        x: event.clientX,
        y: event.clientY,
        offsetX: state.offsetX,
        offsetY: state.offsetY,
        sourceBlankId: state.sourceBlankId,
      });
    } else {
      event.preventDefault();
      setDragGhost((prev) =>
        prev ? { ...prev, x: event.clientX, y: event.clientY } : prev,
      );
    }
    const blankId = resolveDropBlankId(event.clientX, event.clientY);
    setActiveDropBlankId(blankId);
  };

  const finishPointerDrag = (
    event: ReactPointerEvent<HTMLButtonElement>,
    cancelled: boolean,
  ) => {
    const state = pointerDragRef.current;
    if (!state || event.pointerId !== state.pointerId) {
      return;
    }
    pointerDragRef.current = null;
    if (state.dragging) {
      event.preventDefault();
      event.currentTarget.releasePointerCapture?.(event.pointerId);
      suppressClickRef.current = true;
      const blankId = cancelled
        ? null
        : resolveDropBlankId(event.clientX, event.clientY);
      if (blankId) {
        const payload: ClozeDragPayload = {
          cardIndex,
          tokenId: state.tokenId,
          partIndex,
        };
        onTokenDrop(
          createSyntheticDragEvent(payload),
          cardIndex,
          blankId,
          validTokenIds,
          dragBlankIds,
        );
      } else if (state.sourceBlankId) {
        onTokenRemove(cardIndex, state.sourceBlankId);
      }
    }
    setDragGhost(null);
    setActiveDropBlankId(null);
  };

  const handleTokenPointerUp = (event: ReactPointerEvent<HTMLButtonElement>) =>
    finishPointerDrag(event, false);

  const handleTokenPointerCancel = (event: ReactPointerEvent<HTMLButtonElement>) =>
    finishPointerDrag(event, true);

  const handleTokenClick = (
    event: ReactMouseEvent<HTMLButtonElement>,
    tokenId: string,
    tokenValue: string,
    sourceBlankId?: string,
  ) => {
    if (submitted) {
      return;
    }
    if (suppressClickRef.current) {
      suppressClickRef.current = false;
      return;
    }
    event.stopPropagation();
    if (selectedToken?.tokenId === tokenId) {
      setSelectedToken(null);
      return;
    }
    setSelectedToken({ tokenId, tokenValue, sourceBlankId });
  };

  const handleBlankClick = (blankId: string) => {
    if (submitted) {
      return;
    }
    if (!selectedToken) {
      return;
    }
    const payload: ClozeDragPayload = {
      cardIndex,
      tokenId: selectedToken.tokenId,
      partIndex,
    };
    onTokenDrop(
      createSyntheticDragEvent(payload),
      cardIndex,
      blankId,
      validTokenIds,
      dragBlankIds,
    );
    setSelectedToken(null);
  };

  const handleTokenRemoveClick = (blankId: string, tokenId: string) => {
    if (selectedToken?.tokenId === tokenId) {
      setSelectedToken(null);
    }
    onTokenRemove(cardIndex, blankId);
  };

  const renderBlank = (blankId: string) => {
    const segment = blankById.get(blankId);
    if (!segment) {
      return null;
    }
    const blankNumber = blankOrderById.get(blankId) ?? 0;

    if (segment.kind === "input") {
      const value = responses[segment.id] ?? "";
      const isBlankCorrect = reveal
        ? isInputAnswerMatch(value, segment.solution)
        : false;
      const blankClasses = [
        "cloze-blank",
        "input",
        value.trim() ? "filled" : "",
        reveal ? (isBlankCorrect ? "correct" : "incorrect") : "",
      ]
        .filter(Boolean)
        .join(" ");

      return (
        <span className={blankClasses}>
          <input
            type="text"
            className="cloze-input"
            value={value}
            onChange={(event) =>
              onInputChange(cardIndex, segment.id, event.target.value)
            }
            disabled={submitted}
            placeholder="____"
            aria-label={`Blank ${blankNumber}`}
          />
        </span>
      );
    }

    const assignedTokenId = responses[segment.id] ?? "";
    const assignedValue = assignedTokenId
      ? tokenById.get(assignedTokenId) ?? ""
      : "";
    const hasToken = Boolean(assignedValue);
    const isBlankCorrect = reveal
      ? isDragAnswerMatch(assignedValue, segment.solution)
      : false;
    const blankClasses = [
      "cloze-blank",
      "drag",
      hasToken ? "filled" : "",
      activeDropBlankId === segment.id ? "drop-target" : "",
      reveal ? (isBlankCorrect ? "correct" : "incorrect") : "",
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <span
        className={blankClasses}
        aria-label={`Drop zone ${blankNumber}`}
        data-dropzone="cloze-blank"
        data-blank-id={segment.id}
        onClick={() => handleBlankClick(segment.id)}
        onDragOver={onBlankDragOver}
        onDrop={(event) =>
          onTokenDrop(event, cardIndex, segment.id, validTokenIds, dragBlankIds)
        }
      >
        {hasToken ? (
          <span className="cloze-token">
            <button
              type="button"
              className={`token-chip${
                dragGhost?.tokenId === assignedTokenId ? " is-dragging" : ""
              }${selectedToken?.tokenId === assignedTokenId ? " selected" : ""}`}
              draggable={!submitted}
              onDragStart={(event) =>
                onTokenDragStart(event, {
                  cardIndex,
                  tokenId: assignedTokenId,
                  partIndex,
                })
              }
              onClick={(event) =>
                handleTokenClick(event, assignedTokenId, assignedValue, segment.id)
              }
              onPointerDown={(event) =>
                handleTokenPointerDown(event, assignedTokenId, assignedValue, segment.id)
              }
              onPointerMove={handleTokenPointerMove}
              onPointerUp={handleTokenPointerUp}
              onPointerCancel={handleTokenPointerCancel}
              disabled={submitted}
            >
              {assignedValue}
            </button>
            {!submitted ? (
              <button
                type="button"
                className="token-remove"
                onClick={() => handleTokenRemoveClick(segment.id, assignedTokenId)}
                aria-label="Remove token"
              >
                x
              </button>
            ) : null}
          </span>
        ) : (
          <span className="cloze-placeholder">Drop token</span>
        )}
      </span>
    );
  };

  const renderSolutionBlank = (blankId: string) => {
    const segment = blankById.get(blankId);
    if (!segment) {
      return null;
    }
    return <span className="cloze-solution-token">{segment.solution}</span>;
  };

  return (
    <article
      ref={cardRef}
      className={`flashcard-item cloze-card${selectedToken ? " is-selecting" : ""}`}
    >
      {questionText.trim() ? (
        <h3 className="flashcard-question">{questionText}</h3>
      ) : null}
      <MarkdownBlocks
        text={markdownText}
        className="cloze-text"
        allowTableScroll={false}
        renderPlaceholder={renderBlank}
      />
      {hasDragTokens ? (
        <div className="token-section">
          <span className="label">Tokens</span>
          <div className="token-pool">
            {tokenBank.map((token) => {
              const isUsed = assignedTokenIds.has(token.id);
              return (
                <button
                  key={`token-${cardIndex}-${token.id}`}
                  type="button"
                  className={`token-chip ${isUsed ? "used" : ""}${
                    dragGhost?.tokenId === token.id ? " is-dragging" : ""
                  }${selectedToken?.tokenId === token.id ? " selected" : ""}`}
                  draggable={!submitted && !isUsed}
                  onDragStart={(event) =>
                    onTokenDragStart(event, {
                      cardIndex,
                      tokenId: token.id,
                      partIndex,
                    })
                  }
                  onClick={(event) => handleTokenClick(event, token.id, token.value)}
                  onPointerDown={(event) =>
                    handleTokenPointerDown(event, token.id, token.value)
                  }
                  onPointerMove={handleTokenPointerMove}
                  onPointerUp={handleTokenPointerUp}
                  onPointerCancel={handleTokenPointerCancel}
                  disabled={submitted || isUsed}
                >
                  {token.value}
                </button>
              );
            })}
          </div>
        </div>
      ) : null}
      {showActions ? (
        <div className="flashcard-actions">
          {showSubmit ? (
            <button
              type="button"
              className="ghost small flashcard-submit"
              onClick={() => onSubmit(cardIndex, canSubmit)}
              disabled={submitted || !canSubmit || submissionLocked}
            >
              Submit
            </button>
          ) : null}
          {submitted && showResult ? (
            <span className={`flashcard-result ${isCorrect ? "correct" : "incorrect"}`}>
              {resultLabel}
            </span>
          ) : null}
          <HelpButton
            helpText={helpText}
            enabled={helpEnabled}
            className="flashcard-help-button"
          />
        </div>
      ) : null}
      {shouldShowSolution ? (
        <div className="token-solution">
          <span className="label">Solution</span>
          <MarkdownBlocks
            text={markdownText}
            className="cloze-solution"
            allowTableScroll={false}
            renderPlaceholder={renderSolutionBlank}
          />
        </div>
      ) : null}
      {dragGhost && typeof document !== "undefined"
        ? createPortal(
            <div
              className="token-chip token-ghost"
              style={{
                transform: `translate3d(${
                  dragGhost.x - dragGhost.offsetX
                }px, ${dragGhost.y - dragGhost.offsetY}px, 0)`,
              }}
              aria-hidden="true"
            >
              {dragGhost.tokenValue}
            </div>,
            document.body,
          )
        : null}
    </article>
  );
};

/**
 * @file apps/fmd-desktop/src/components/flashcards/CompositeCard.tsx
 *
 * Zweck:
 * - Rendert die UI-Komponente Composite Card.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/components/flashcards/ClozeCard.tsx: UI-Komponente.
 * - apps/fmd-desktop/src/components/flashcards/FreeTextCard.tsx: UI-Komponente.
 * - apps/fmd-desktop/src/components/flashcards/MultipleChoiceCard.tsx: UI-Komponente.
 *
 * Exportiert:
 * - CompositeCard: React-Komponente.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import type { DragEvent } from "react";
import { ClozeCard } from "./ClozeCard";
import { FreeTextCard } from "./FreeTextCard";
import { MultipleChoiceCard } from "./MultipleChoiceCard";
import { TrueFalseCard } from "./TrueFalseCard";
import type { CompositeFlashcard } from "../../lib/flashcards";
import {
  evaluateCompositeCardResult,
  isFlashcardPartComplete,
  type CompositePartState,
  type FlashcardSelfGrade,
  type TrueFalseSelection,
} from "../../features/flashcards/logic";
import { HelpButton, hasHelpContent } from "../HelpButton";

type CompositeCardProps = {
  card: CompositeFlashcard;
  cardIndex: number;
  submitted: boolean;
  submissionLocked?: boolean;
  partStates: CompositePartState[];
  showSubmit?: boolean;
  showResult?: boolean;
  revealCorrectness?: boolean;
  showSolution?: boolean;
  forceRevealText?: boolean;
  helpText?: string[] | string;
  helpEnabled?: boolean;
  onOptionSelect: (cardIndex: number, partIndex: number, keys: string[]) => void;
  onTrueFalseSelect: (
    cardIndex: number,
    partIndex: number,
    itemId: string,
    value: TrueFalseSelection,
  ) => void;
  onClozeInputChange: (
    cardIndex: number,
    partIndex: number,
    blankId: string,
    value: string,
  ) => void;
  onClozeTokenDrop: (
    event: DragEvent<HTMLElement>,
    cardIndex: number,
    partIndex: number,
    blankId: string,
    validTokenIds: Set<string>,
    dragBlankIds: Set<string>,
  ) => void;
  onClozeTokenRemove: (cardIndex: number, partIndex: number, blankId: string) => void;
  onClozeTokenDragStart: (
    event: DragEvent<HTMLElement>,
    payload: { cardIndex: number; tokenId: string; partIndex?: number },
  ) => void;
  onBlankDragOver: (event: DragEvent<HTMLElement>) => void;
  onTextInputChange: (cardIndex: number, partIndex: number, value: string) => void;
  onTextCheck: (cardIndex: number, partIndex: number) => void;
  onSelfGrade: (
    cardIndex: number,
    partIndex: number,
    grade: FlashcardSelfGrade,
  ) => void;
  onSubmit: (cardIndex: number, canSubmit: boolean) => void;
};

export const CompositeCard = ({
  card,
  cardIndex,
  submitted,
  submissionLocked = false,
  partStates,
  showSubmit = true,
  showResult = true,
  revealCorrectness,
  showSolution,
  forceRevealText = false,
  helpText,
  helpEnabled,
  onBlankDragOver,
  onClozeInputChange,
  onClozeTokenDragStart,
  onClozeTokenDrop,
  onClozeTokenRemove,
  onOptionSelect,
  onSelfGrade,
  onSubmit,
  onTextCheck,
  onTextInputChange,
  onTrueFalseSelect,
}: CompositeCardProps) => {
  const canSubmit =
    card.parts.length > 0 &&
    card.parts.every((part, index) => {
      if (part.kind === "free-text") {
        return true;
      }
      return isFlashcardPartComplete(part, partStates[index] ?? {});
    });
  const cardResult = evaluateCompositeCardResult(card, partStates);
  const showResultLabel = submitted && showResult;
  const resultLabel = showResultLabel
    ? cardResult === "pending"
      ? "Pending"
      : cardResult === "correct"
        ? "Correct"
        : "Incorrect"
    : "";
  const resultClass = `flashcard-result ${
    cardResult === "pending"
      ? "pending"
      : cardResult === "correct"
        ? "correct"
        : "incorrect"
  }`;
  const hasHelp = helpEnabled && hasHelpContent(helpText);
  const showActions = showSubmit || (submitted && showResult) || hasHelp;

  return (
    <article className="flashcard-item composite-card">
      <div className="composite-parts">
        {card.parts.map((part, partIndex) => {
          const state = partStates[partIndex] ?? {};
          if (part.kind === "cloze") {
            return (
              <ClozeCard
                key={`composite-${cardIndex}-${partIndex}`}
                card={part}
                cardIndex={cardIndex}
                partIndex={partIndex}
                submitted={submitted}
                submissionLocked={submissionLocked}
                responses={state.clozeResponses ?? {}}
                showResult={showResult}
                revealCorrectness={revealCorrectness}
                showSolution={showSolution}
                onInputChange={(index, blankId, value) =>
                  onClozeInputChange(index, partIndex, blankId, value)
                }
                onTokenDrop={(event, index, blankId, validTokenIds, dragBlankIds) =>
                  onClozeTokenDrop(
                    event,
                    index,
                    partIndex,
                    blankId,
                    validTokenIds,
                    dragBlankIds,
                  )
                }
                onTokenRemove={(index, blankId) =>
                  onClozeTokenRemove(index, partIndex, blankId)
                }
                onTokenDragStart={onClozeTokenDragStart}
                onBlankDragOver={onBlankDragOver}
                onSubmit={onSubmit}
                showSubmit={false}
              />
            );
          }

          if (part.kind === "true-false") {
            return (
              <TrueFalseCard
                key={`composite-${cardIndex}-${partIndex}`}
                card={part}
                cardIndex={cardIndex}
                submitted={submitted}
                submissionLocked={submissionLocked}
                selections={state.trueFalseSelections ?? {}}
                showResult={showResult}
                revealCorrectness={revealCorrectness}
                showSolution={showSolution}
                onSelect={(index, itemId, value) =>
                  onTrueFalseSelect(index, partIndex, itemId, value)
                }
                onSubmit={onSubmit}
                showSubmit={false}
              />
            );
          }

          if (part.kind === "free-text") {
            return (
              <FreeTextCard
                key={`composite-${cardIndex}-${partIndex}`}
                card={part}
                cardIndex={cardIndex}
                submitted={submitted}
                submissionLocked={submissionLocked}
                response={state.textResponse ?? ""}
                revealed={forceRevealText || state.textRevealed || false}
                selfGrade={state.selfGrade}
                showActions={showResult}
                onInputChange={(index, value) =>
                  onTextInputChange(index, partIndex, value)
                }
                onCheck={(index) => onTextCheck(index, partIndex)}
                onSelfGrade={(index, grade) => onSelfGrade(index, partIndex, grade)}
              />
            );
          }

          return (
              <MultipleChoiceCard
                key={`composite-${cardIndex}-${partIndex}`}
                card={part}
                cardIndex={cardIndex}
                submitted={submitted}
                submissionLocked={submissionLocked}
                selectedKeys={state.selections ?? []}
                showResult={showResult}
                revealCorrectness={revealCorrectness}
                onSelect={(index, keys) => onOptionSelect(index, partIndex, keys)}
                onSubmit={onSubmit}
                showSubmit={false}
              />
          );
        })}
      </div>
      {showActions ? (
        <div className="flashcard-actions">
          {showSubmit ? (
            <button
              type="button"
              className="ghost small flashcard-submit"
              onClick={() => onSubmit(cardIndex, canSubmit)}
              disabled={!canSubmit || submitted || submissionLocked}
            >
              Submit
            </button>
          ) : null}
          {showResultLabel ? (
            <span className={resultClass}>{resultLabel}</span>
          ) : null}
          <HelpButton
            helpText={helpText}
            enabled={helpEnabled}
            className="flashcard-help-button"
          />
        </div>
      ) : null}
    </article>
  );
};

/**
 * @file apps/fmd-desktop/src/components/flashcards/FreeTextCard.tsx
 *
 * Zweck:
 * - Rendert die UI-Komponente Free Text Card.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/lib/flashcards.ts: Typen.
 * - apps/fmd-desktop/src/features/flashcards/logic.ts: Typen.
 *
 * Exportiert:
 * - FreeTextCard: React-Komponente.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import type { FreeTextCard as FreeTextCardType } from "../../lib/flashcards";
import { MarkdownBlocks } from "./MarkdownBlocks";
import type { FlashcardSelfGrade } from "../../features/flashcards/logic";
import { HelpButton, hasHelpContent } from "../HelpButton";

type FreeTextCardProps = {
  card: FreeTextCardType;
  cardIndex: number;
  submitted: boolean;
  response: string;
  revealed: boolean;
  selfGrade?: FlashcardSelfGrade;
  submissionLocked?: boolean;
  showActions?: boolean;
  helpText?: string[] | string;
  helpEnabled?: boolean;
  onInputChange: (cardIndex: number, value: string) => void;
  onCheck: (cardIndex: number) => void;
  onSelfGrade: (cardIndex: number, grade: FlashcardSelfGrade) => void;
};

export const FreeTextCard = ({
  card,
  cardIndex,
  submitted,
  response,
  revealed,
  selfGrade,
  submissionLocked = false,
  showActions = true,
  helpText,
  helpEnabled,
  onInputChange,
  onCheck,
  onSelfGrade,
}: FreeTextCardProps) => {
  const hasInput = response.trim().length > 0;
  const resultLabel = submitted
    ? selfGrade === "correct"
      ? "Correct"
      : "Incorrect"
    : "";
  const isCorrectSelected = selfGrade === "correct";
  const isIncorrectSelected = selfGrade === "incorrect";
  const hasHelp = helpEnabled && hasHelpContent(helpText);
  const showActionsResolved = showActions || hasHelp;

  return (
    <article className="flashcard-item free-text-card">
      {card.front.trim() ? (
        <MarkdownBlocks
          text={card.front}
          className="flashcard-text-block"
          allowTableScroll
        />
      ) : null}
      <textarea
        className="flashcard-input"
        value={response}
        onChange={(event) => onInputChange(cardIndex, event.target.value)}
        placeholder="Your answer"
        aria-label="Your answer"
        disabled={submitted || revealed}
      />
      {showActionsResolved ? (
        <div className="flashcard-actions">
          {!revealed ? (
            <button
              type="button"
              className="ghost small flashcard-submit"
              onClick={() => onCheck(cardIndex)}
              disabled={!hasInput || submitted || submissionLocked}
            >
              Check
            </button>
          ) : (
            <>
              <button
                type="button"
                className={`${
                  isCorrectSelected ? "primary" : "ghost"
                } small flashcard-submit`}
                onClick={() => onSelfGrade(cardIndex, "correct")}
                aria-pressed={isCorrectSelected}
                disabled={submitted || submissionLocked}
              >
                Correct
              </button>
              <button
                type="button"
                className={`${
                  isIncorrectSelected ? "primary" : "ghost"
                } small flashcard-submit`}
                onClick={() => onSelfGrade(cardIndex, "incorrect")}
                aria-pressed={isIncorrectSelected}
                disabled={submitted || submissionLocked}
              >
                Incorrect
              </button>
            </>
          )}
          {submitted ? (
            <span
              className={`flashcard-result ${
                selfGrade === "correct" ? "correct" : "incorrect"
              }`}
            >
              {resultLabel}
            </span>
          ) : null}
          <HelpButton
            helpText={helpText}
            enabled={helpEnabled}
            className="flashcard-help-button"
          />
        </div>
      ) : null}
      {revealed ? (
        <div className="flashcard-answer">
          <span className="label">Answer</span>
          <MarkdownBlocks
            text={card.back}
            className="flashcard-answer-text"
            allowTableScroll
          />
        </div>
      ) : null}
    </article>
  );
};

/**
 * @file apps/fmd-desktop/src/components/flashcards/MarkdownBlocks.tsx
 *
 * Zweck:
 * - Rendert einfache Markdown-Bloecke mit Tabellenunterstuetzung.
 *
 * Hinweise:
 * - Tabellen werden als pipe tables erkannt.
 * - Platzhalter fuer Cloze-Token koennen via renderPlaceholder ersetzt werden.
 */

import { Fragment, type ReactNode } from "react";
import { splitMarkdownBlocks, type MarkdownBlock } from "../../lib/markdownTables";

export const CLOZE_PLACEHOLDER_PREFIX = "@@@CLOZE:";
export const CLOZE_PLACEHOLDER_SUFFIX = "@@@";

const buildPlaceholder = (id: string) =>
  `${CLOZE_PLACEHOLDER_PREFIX}${id}${CLOZE_PLACEHOLDER_SUFFIX}`;

type Token =
  | { type: "text"; value: string }
  | { type: "br" }
  | { type: "placeholder"; id: string };

const tokenRegex = /@@@CLOZE:([^@]+?)@@@|<br\s*\/?>/gi;

const tokenizeText = (value: string) => {
  const tokens: Token[] = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null = null;
  tokenRegex.lastIndex = 0;

  while ((match = tokenRegex.exec(value)) !== null) {
    if (match.index > lastIndex) {
      tokens.push({
        type: "text",
        value: value.slice(lastIndex, match.index),
      });
    }

    if (match[1]) {
      tokens.push({ type: "placeholder", id: match[1] });
    } else {
      tokens.push({ type: "br" });
    }

    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < value.length) {
    tokens.push({ type: "text", value: value.slice(lastIndex) });
  }

  return tokens;
};

const renderTokens = (
  value: string,
  renderPlaceholder: ((id: string) => ReactNode) | undefined,
  keyPrefix: string,
) =>
  tokenizeText(value).map((token, index) => {
    const key = `${keyPrefix}-${index}`;
    if (token.type === "text") {
      return token.value;
    }
    if (token.type === "br") {
      return <br key={key} />;
    }
    if (!renderPlaceholder) {
      return buildPlaceholder(token.id);
    }
    const rendered = renderPlaceholder(token.id);
    if (rendered === null || rendered === undefined) {
      return buildPlaceholder(token.id);
    }
    return <Fragment key={key}>{rendered}</Fragment>;
  });

type MarkdownFenceBlock =
  | { type: "code"; text: string; language: string }
  | { type: "text"; text: string };

const normalizeLineBreaks = (value: string) => value.replace(/\r\n?/g, "\n");

const splitFenceBlocks = (rawText: string): MarkdownFenceBlock[] => {
  const lines = normalizeLineBreaks(rawText).split("\n");
  const blocks: MarkdownFenceBlock[] = [];
  const textBuffer: string[] = [];
  const codeBuffer: string[] = [];
  let inFence = false;
  let fenceLanguage = "";
  const fencePattern = /^(```|~~~)(.*)$/;

  const flushText = () => {
    if (textBuffer.length === 0) {
      return;
    }
    blocks.push({ type: "text", text: textBuffer.join("\n") });
    textBuffer.length = 0;
  };

  const flushCode = () => {
    blocks.push({ type: "code", text: codeBuffer.join("\n"), language: fenceLanguage });
    codeBuffer.length = 0;
    fenceLanguage = "";
  };

  lines.forEach((line) => {
    const trimmed = line.trimStart();
    const match = trimmed.match(fencePattern);
    if (match) {
      if (inFence) {
        flushCode();
        inFence = false;
      } else {
        flushText();
        inFence = true;
        fenceLanguage = match[2]?.trim() ?? "";
      }
      return;
    }
    if (inFence) {
      codeBuffer.push(line);
    } else {
      textBuffer.push(line);
    }
  });

  if (inFence) {
    flushCode();
  } else {
    flushText();
  }

  return blocks;
};

type MarkdownBlocksProps = {
  text: string;
  className?: string;
  allowTableScroll?: boolean;
  renderPlaceholder?: (id: string) => ReactNode;
};

export const MarkdownBlocks = ({
  text,
  className,
  allowTableScroll = true,
  renderPlaceholder,
}: MarkdownBlocksProps) => {
  const fencedBlocks = splitFenceBlocks(text);
  const blocks: Array<MarkdownBlock | MarkdownFenceBlock> = [];
  fencedBlocks.forEach((block) => {
    if (block.type === "code") {
      blocks.push(block);
      return;
    }
    splitMarkdownBlocks(block.text).forEach((nested) => {
      blocks.push(nested);
    });
  });
  const containerClass = ["flashcard-markdown", className]
    .filter(Boolean)
    .join(" ");
  const tableClass = [
    "flashcard-table",
    allowTableScroll ? "scrollable" : "no-scroll",
  ].join(" ");

  return (
    <div className={containerClass}>
      {blocks.map((block, blockIndex) => {
        if (block.type === "table") {
          return (
            <div className={tableClass} key={`table-${blockIndex}`}>
              <table>
                <thead>
                  <tr>
                    {block.header.map((cell, cellIndex) => (
                      <th key={`head-${blockIndex}-${cellIndex}`}>
                        {renderTokens(
                          cell,
                          renderPlaceholder,
                          `table-head-${blockIndex}-${cellIndex}`,
                        )}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {block.rows.map((row, rowIndex) => (
                    <tr key={`row-${blockIndex}-${rowIndex}`}>
                      {row.map((cell, cellIndex) => (
                        <td key={`cell-${blockIndex}-${rowIndex}-${cellIndex}`}>
                          {renderTokens(
                            cell,
                            renderPlaceholder,
                            `table-cell-${blockIndex}-${rowIndex}-${cellIndex}`,
                          )}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }

        if (block.type === "code") {
          const codeClass = [
            "flashcard-code-block",
            block.language ? `language-${block.language}` : "",
          ]
            .filter(Boolean)
            .join(" ");
          return (
            <pre className={codeClass} key={`code-${blockIndex}`}>
              <code>
                {renderTokens(block.text, renderPlaceholder, `code-${blockIndex}`)}
              </code>
            </pre>
          );
        }

        return (
          <div className="flashcard-markdown-text" key={`text-${blockIndex}`}>
            {renderTokens(block.text, renderPlaceholder, `text-${blockIndex}`)}
          </div>
        );
      })}
    </div>
  );
};

/**
 * @file apps/fmd-desktop/src/components/flashcards/MultipleChoiceCard.tsx
 *
 * Zweck:
 * - Rendert die UI-Komponente Multiple Choice Card.
 *
 * Verantwortlichkeiten:
 * - Baut die UI-Struktur und zugehoerige Klassen auf.
 * - Verdrahtet Props und Callbacks mit Unterkomponenten.
 * - Stellt Inhalts- und Statusvarianten dar.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/lib/flashcards.ts: Typen.
 * - apps/fmd-desktop/src/components/flashcards/CompositeCard.tsx: Nutzt dieses Modul.
 *
 * Exportiert:
 * - MultipleChoiceCard: React-Komponente.
 *
 * Hinweise:
 * - Styling erfolgt ueber globale CSS-Klassen und Variablen.
 */

import { useId, useMemo } from "react";
import { type MultipleChoiceCard as MultipleChoiceCardType } from "../../lib/flashcards";
import { MarkdownBlocks } from "./MarkdownBlocks";
import { HelpButton, hasHelpContent } from "../HelpButton";

const OPTION_LABELS = "abcdefghijklmnopqrstuvwxyz";

const indexToLabel = (index: number) => {
  let label = "";
  let cursor = index;
  do {
    label = OPTION_LABELS[cursor % 26] + label;
    cursor = Math.floor(cursor / 26) - 1;
  } while (cursor >= 0);
  return label;
};

const shuffleOptions = <T,>(options: T[]) => {
  const copy = [...options];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]];
  }
  return copy;
};

const isExactKeyMatch = (selected: string[], correct: string[]) => {
  if (selected.length !== correct.length) {
    return false;
  }
  const selectedSet = new Set(selected);
  if (selectedSet.size !== correct.length) {
    return false;
  }
  return correct.every((key) => selectedSet.has(key));
};

type MultipleChoiceCardProps = {
  card: MultipleChoiceCardType;
  cardIndex: number;
  submitted: boolean;
  selectedKeys: string[];
  submissionLocked?: boolean;
  showSubmit?: boolean;
  showResult?: boolean;
  revealCorrectness?: boolean;
  helpText?: string[] | string;
  helpEnabled?: boolean;
  onSelect: (cardIndex: number, keys: string[]) => void;
  onSubmit: (cardIndex: number, canSubmit: boolean) => void;
};

export const MultipleChoiceCard = ({
  card,
  cardIndex,
  submitted,
  selectedKeys,
  submissionLocked = false,
  showSubmit = true,
  showResult = true,
  revealCorrectness,
  helpText,
  helpEnabled,
  onSelect,
  onSubmit,
}: MultipleChoiceCardProps) => {
  const inputGroup = useId();
  const hasSolutions = card.correctKeys.length > 0;
  const isMultiSelect = card.correctKeys.length > 1;
  const selectionIsCorrect =
    hasSolutions && selectedKeys.length > 0
      ? isExactKeyMatch(selectedKeys, card.correctKeys)
      : false;
  const reveal = revealCorrectness ?? submitted;
  const resultLabel = submitted && showResult
    ? hasSolutions
      ? selectionIsCorrect
        ? "Correct"
        : "Incorrect"
      : "No solution defined"
    : "";

  const cardSignature = useMemo(() => {
    const optionsSignature = card.options
      .map((option) => `${option.key}:${option.text}`)
      .join("|");
    return [card.question, card.correctKeys.join(","), optionsSignature].join("::");
  }, [card.question, card.correctKeys, card.options]);

  const displayOptions = useMemo(
    () =>
      shuffleOptions(card.options).map((option, index) => ({
        option,
        label: indexToLabel(index),
      })),
    [cardSignature],
  );

  const hasHelp = helpEnabled && hasHelpContent(helpText);
  const showActions = showSubmit || (submitted && showResult) || hasHelp;

  return (
    <article className="flashcard-item">
      <h3 className="flashcard-question">{card.question}</h3>
      {card.context?.trim() ? (
        <MarkdownBlocks text={card.context} allowTableScroll />
      ) : null}
      <ul className="flashcard-options">
        {displayOptions.map(({ option, label }) => {
          const isSelected = selectedKeys.includes(option.key);
          const isCorrect = hasSolutions && card.correctKeys.includes(option.key);
          const isIncorrect = hasSolutions && reveal && isSelected && !isCorrect;
          const isDisabled = submitted || submissionLocked;
          const optionClasses = [
            "flashcard-option",
            isSelected ? "selected" : "",
            reveal && isCorrect ? "correct" : "",
            reveal && isIncorrect ? "incorrect" : "",
            isDisabled ? "disabled" : "",
          ]
            .filter(Boolean)
            .join(" ");

          const handleSelect = () => {
            if (isDisabled) {
              return;
            }
            if (isMultiSelect) {
              const nextKeys = isSelected
                ? selectedKeys.filter((key) => key !== option.key)
                : [...selectedKeys, option.key];
              onSelect(cardIndex, nextKeys);
              return;
            }
            onSelect(cardIndex, [option.key]);
          };

          return (
            <li key={`flashcard-${cardIndex}-${option.key}`}>
              <label className={optionClasses}>
                <input
                  type={isMultiSelect ? "checkbox" : "radio"}
                  name={`flashcard-${cardIndex}-${inputGroup}`}
                  checked={isSelected}
                  onChange={handleSelect}
                  disabled={isDisabled}
                  className="flashcard-option-input"
                />
                <span className="flashcard-key">{label}</span>
                <MarkdownBlocks
                  text={option.text}
                  className="flashcard-text"
                  allowTableScroll
                />
              </label>
            </li>
          );
        })}
      </ul>
      {showActions ? (
        <div className="flashcard-actions">
          {showSubmit ? (
            <button
              type="button"
              className="ghost small flashcard-submit"
              onClick={() => onSubmit(cardIndex, selectedKeys.length > 0)}
              disabled={selectedKeys.length === 0 || submitted || submissionLocked}
            >
              Submit
            </button>
          ) : null}
          {submitted && showResult ? (
            <span
              className={`flashcard-result ${
                hasSolutions ? (selectionIsCorrect ? "correct" : "incorrect") : "neutral"
              }`}
            >
              {resultLabel}
            </span>
          ) : null}
          <HelpButton
            helpText={helpText}
            enabled={helpEnabled}
            className="flashcard-help-button"
          />
        </div>
      ) : null}
    </article>
  );
};

/**
