describe("NoteModal", () => {
  it("toggles aria-expanded and closes via ESC and backdrop", () => {
    const Harness = () => {
      const [open, setOpen] = useState(false);
      return (
        <>
          <button
            type="button"
            aria-label="Open note"
            aria-haspopup="dialog"
            aria-expanded={open}
            title="Note"
            onClick={() => setOpen(true)}
          >
            Note
          </button>
          <NoteModal isOpen={open} onClose={() => setOpen(false)}>
            <div>Note Files</div>
          </NoteModal>
        </>
      );
