    expect(lines).toContain("---");
    expect(lines).toContain("-b");
    expect(lines.some((line) => line.trim() === "#card")).toBe(true);
    expect(lines.some((line) => line.trim() === "#")).toBe(true);

    const promptLine = lines.find((line) => line.startsWith("1\\) Prompt line"));
