                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
          <div className="setting-row">
            <span className="label">Markdown view edit (experimental)</span>
            <div className="theme-toggle">
              <span className="toggle-label">Off</span>
              <label className="switch">
