/**
 * @file apps/fmd-desktop/src/components/StudySectionNav.tsx
 *
 * Zweck:
 * - Rendert die kompakte Studien-Sektion-Navigation.
 */

import {
  type ComponentType,
  type RefObject,
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  CardsIcon,
  ExamEditorIcon,
  FolderIcon,
  GaugeIcon,
  MarkdownIcon,
  MenuIcon,
  RefreshIcon,
} from "./icons";
import { STUDY_SECTIONS, type StudySectionKey } from "../lib/studySections";

type StudySectionNavProps = {
  activeTab: StudySectionKey;
  onSectionSelect: (tab: StudySectionKey) => void;
  isMobileNavOpen: boolean;
  onMobileNavOpen: () => void;
  showNoteAction?: boolean;
  onNoteAction?: () => void;
  noteActionRef?: RefObject<HTMLButtonElement | null>;
  isNoteActionActive?: boolean;
};

const SECTION_ICONS: Record<StudySectionKey, ComponentType> = {
  dashboard: FolderIcon,
  exam: ExamEditorIcon,
  flashcard: CardsIcon,
  "fast-flashcard": GaugeIcon,
  "spaced-repetition": RefreshIcon,
};

export const StudySectionNav = ({
  activeTab,
  onSectionSelect,
  isMobileNavOpen,
  onMobileNavOpen,
  showNoteAction = false,
  onNoteAction,
  noteActionRef,
  isNoteActionActive = false,
}: StudySectionNavProps) => {
  const [isIconOnly, setIsIconOnly] = useState(false);
  const navRef = useRef<HTMLElement | null>(null);
  const measureRef = useRef<HTMLDivElement | null>(null);
  const noteLabel = "Note";

  const evaluateOverflow = useCallback(() => {
    const navElement = navRef.current;
    const measureElement = measureRef.current;
    if (!navElement || !measureElement) {
      return;
    }
    const availableWidth = navElement.clientWidth;
    const requiredWidth = measureElement.scrollWidth;
    const shouldUseIcons = requiredWidth > availableWidth + 1;
    setIsIconOnly((prev) => (prev === shouldUseIcons ? prev : shouldUseIcons));
  }, []);

  useLayoutEffect(() => {
    const navElement = navRef.current;
    const measureElement = measureRef.current;
    if (!navElement || !measureElement) {
      return;
    }

    let frame = 0;
    const scheduleMeasure = () => {
      if (frame) {
        cancelAnimationFrame(frame);
      }
      frame = requestAnimationFrame(evaluateOverflow);
    };

    scheduleMeasure();

    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", scheduleMeasure);
      return () => {
        if (frame) {
          cancelAnimationFrame(frame);
        }
        window.removeEventListener("resize", scheduleMeasure);
      };
    }

    const observer = new ResizeObserver(scheduleMeasure);
    observer.observe(navElement);
    observer.observe(measureElement);

    return () => {
      if (frame) {
        cancelAnimationFrame(frame);
      }
      observer.disconnect();
    };
  }, [evaluateOverflow]);

  return (
    <>
      <nav
        ref={navRef}
        className={`study-section-nav ${isIconOnly ? "icon-only" : ""}`}
        aria-label="Study sections"
      >
        <button
          type="button"
          className="nav-item study-section-menu-toggle"
          onClick={onMobileNavOpen}
          aria-label="Open navigation"
          aria-controls="app-sidebar"
          aria-expanded={isMobileNavOpen}
        >
          <MenuIcon />
        </button>
        {STUDY_SECTIONS.map((section) => {
          const isActive = activeTab === section.key;
          const Icon = SECTION_ICONS[section.key];
          return (
            <button
              key={section.key}
              type="button"
              className={`nav-item study-section-tab ${isActive ? "active" : ""}`}
              onClick={() => onSectionSelect(section.key)}
              aria-pressed={isActive}
              aria-label={isIconOnly ? section.label : undefined}
              title={isIconOnly ? section.label : undefined}
            >
              {isIconOnly ? <Icon /> : section.label}
            </button>
          );
        })}
        {showNoteAction ? (
          <button
            ref={noteActionRef}
            type="button"
            className={`nav-item study-section-note-toggle ${
              isNoteActionActive ? "active" : ""
            }`}
            onClick={onNoteAction}
            aria-label="Open note"
            aria-haspopup="dialog"
            aria-expanded={isNoteActionActive}
            title={noteLabel}
          >
            <MarkdownIcon />
          </button>
        ) : null}
      </nav>
      <div
        ref={measureRef}
        className="study-section-nav study-section-nav-measure"
        aria-hidden="true"
      >
        <span className="nav-item study-section-menu-toggle" aria-hidden="true">
          <MenuIcon />
        </span>
        {STUDY_SECTIONS.map((section) => (
          <span key={section.key} className="nav-item study-section-tab">
            {section.label}
          </span>
        ))}
        {showNoteAction ? (
          <span className="nav-item study-section-note-toggle" aria-hidden="true">
            <MarkdownIcon />
          </span>
        ) : null}
      </div>
    </>
  );
};

/**
 * @file apps/fmd-desktop/src/components/StudyTimeBar.tsx
 *
 * Zweck:
 * - Schlanker Progress-Bar fuer Study-View-Header.
 */

import { useMemo, type CSSProperties } from "react";

type StudyTimeBarProps = {
  elapsedMs: number;
  maxMs: number | null;
  isRunning: boolean;
};

export const StudyTimeBar = ({ elapsedMs, maxMs, isRunning }: StudyTimeBarProps) => {
  const progressStyle = useMemo(() => {
    if (!maxMs || maxMs <= 0) {
      return undefined;
    }
    const progress = Math.max(0, Math.min(1, elapsedMs / maxMs));
    return { "--study-time-progress": `${Math.round(progress * 100)}%` } as CSSProperties;
  }, [elapsedMs, maxMs]);

  const isIndeterminate = !maxMs || maxMs <= 0;
  const className = [
    "study-time-bar",
    isIndeterminate ? "is-indeterminate" : "",
    !isRunning ? "is-paused" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return <div className={className} style={progressStyle} aria-hidden="true" />;
};

/**
 * @file apps/fmd-desktop/src/components/UserToolsPanel.tsx
 *
 * Zweck:
 * - Rendert die User Tools fuer Study/Spaced Repetition und Exam.
 *
 * Verantwortlichkeiten:
 * - Zeigt Active User, Start und User-Management an.
 * - Teilt Layout und Logik zwischen Study und Exam.
 */

import { CollapsiblePanelHeader } from "./CollapsiblePanelHeader";

export type ExamStageControls = {
  stage: "idle" | "running" | "review" | "scoring" | "finished";
  canStartExam: boolean;
  finishPending?: boolean;
  onStartExam: () => void;
  onSubmitExam: () => void;
  onStartScoring: () => void;
  onFinishScoring: () => void;
  onResetExam: () => void;
};

type ExamPhaseButton = {
  label: string;
  onClick: () => void;
  disabled: boolean;
};

export type ExamPrimaryButton = {
  label: string;
  onClick: () => void;
  disabled: boolean;
  variant: "primary" | "ghost";
};

export const resolveExamPhaseButton = (
  examStageControls: ExamStageControls,
): ExamPhaseButton => {
  switch (examStageControls.stage) {
    case "idle":
      return {
        label: "Start",
        onClick: examStageControls.onStartExam,
        disabled: !examStageControls.canStartExam,
      };
    case "running":
      return {
        label: "Submit",
        onClick: examStageControls.onSubmitExam,
        disabled: false,
      };
    case "review":
      return {
        label: "Exam",
        onClick: examStageControls.onStartScoring,
        disabled: false,
      };
    case "scoring":
      return {
        label: "Grading",
        onClick: examStageControls.onFinishScoring,
        disabled: Boolean(examStageControls.finishPending),
      };
    case "finished":
    default:
      return {
        label: "Grading",
        onClick: examStageControls.onFinishScoring,
        disabled: true,
      };
  }
};

export const resolveExamPrimaryButton = (
  examStageControls: ExamStageControls,
): ExamPrimaryButton => {
  if (examStageControls.stage === "finished") {
    return {
      label: "Reset",
      onClick: examStageControls.onResetExam,
      disabled: false,
      variant: "ghost",
    };
  }
  const phaseButton = resolveExamPhaseButton(examStageControls);
  return {
    ...phaseButton,
    variant: "primary",
  };
};

type UserToolsPanelProps = {
  spacedRepetition: {
    spacedRepetitionActiveUser: string | null;
    spacedRepetitionSelectedUserId: string;
    spacedRepetitionUsers: { id: string; name: string }[];
    spacedRepetitionNewUserName: string;
    spacedRepetitionUserError: string;
    handleSpacedRepetitionActiveUserLoadCards: () => void;
    setSpacedRepetitionSelectedUserId: (value: string) => void;
    setSpacedRepetitionNewUserName: (value: string) => void;
    setSpacedRepetitionUserError: (value: string) => void;
    handleSpacedRepetitionCreateUser: () => void;
    handleSpacedRepetitionLoadUser: () => void;
  };
  handleDeleteOpen: () => void;
  onStart: () => void;
  startDisabled: boolean;
  showReset?: boolean;
  onReset?: () => void;
  examStageControls?: ExamStageControls;
  isCollapsible?: boolean;
  isCollapsed?: boolean;
  onToggleCollapse?: () => void;
  controlsId?: string;
};

export const UserToolsPanel = ({
  spacedRepetition,
  handleDeleteOpen,
  onStart,
  startDisabled,
  showReset = false,
  onReset,
  examStageControls,
  isCollapsible = false,
  isCollapsed = false,
  onToggleCollapse,
  controlsId,
}: UserToolsPanelProps) => {
  const phaseButton = examStageControls
    ? resolveExamPhaseButton(examStageControls)
    : null;

  return (
    <section className="panel sr-user-panel">
      {isCollapsible && onToggleCollapse && controlsId ? (
        <CollapsiblePanelHeader
          title="User Tools"
          isCollapsed={isCollapsed}
          onToggle={onToggleCollapse}
          controlsId={controlsId}
        />
      ) : (
        <div className="panel-header">
          <div>
            <h2>User Tools</h2>
          </div>
        </div>
      )}
      <div
        className="panel-body"
        id={controlsId}
        hidden={Boolean(isCollapsible && isCollapsed)}
        aria-hidden={Boolean(isCollapsible && isCollapsed)}
      >
        <div className="setting-row">
          <div className="setting-inline sr-user-actions">
            {phaseButton ? (
              <>
                <button
                  type="button"
                  className="primary small"
                  onClick={phaseButton.onClick}
                  disabled={phaseButton.disabled}
                >
                  {phaseButton.label}
                </button>
                <button
                  type="button"
                  className="ghost small"
                  onClick={examStageControls?.onResetExam}
                  aria-label="Reset session"
                >
                  Reset
                </button>
