 */

import { describe, expect, it, vi } from "vitest";
import { normalizeSettings, type AppSettings } from "./useAppSettings";

vi.mock("@tauri-apps/api/core", () => ({
  invoke: vi.fn(),
}));

describe("normalizeSettings", () => {
