  boxCanonical: number;
  attempts: number;
  lastResult: FlashcardResult;
  lastReviewedAt: string | null;
};

type SpacedRepetitionCardProgressInput = Partial<SpacedRepetitionCardProgress> & {
  box?: number;
  boxCanonical?: number;
};

