export const useVault = ({ persistSettings, showHiddenFolders }: UseVaultOptions) => {
  const [vaultPath, setVaultPath] = useState<string | null>(null);
  const [files, setFiles] = useState<VaultFile[]>([]);
  const [folders, setFolders] = useState<string[]>([]);
  const [listState, setListState] = useState<LoadState>("idle");
  const [listError, setListError] = useState("");
  const [lastRefreshAt, setLastRefreshAt] = useState<string | null>(null);
  const lastRescanHiddenState = useRef(showHiddenFolders);

  const takeSnapshot = useCallback(
    (): VaultSnapshot => ({
      vaultPath,
      files,
      folders,
      listState,
      listError,
      lastRefreshAt,
    }),
    [files, folders, lastRefreshAt, listError, listState, vaultPath],
  );

  const restoreSnapshot = useCallback((snapshot: VaultSnapshot) => {
    setVaultPath(snapshot.vaultPath);
    setFiles(snapshot.files);
    setFolders(snapshot.folders);
    setListState(snapshot.listState);
    setListError(snapshot.listError);
    setLastRefreshAt(snapshot.lastRefreshAt);
  }, []);

  const loadVault = useCallback(
    async (path: string, options: LoadOptions): Promise<VaultScanResults | null> => {
      setListError("");
      setVaultPath(path);
      setFiles([]);
      setFolders([]);
      setListState("loading");
      try {
        const results = await invoke<VaultScanResults>("list_vault_entries", {
          vaultPath: path,
          showHiddenFolders,
        });
        setFiles(results.files);
        setFolders(results.folders);
        setLastRefreshAt(new Date().toISOString());
        setListState("idle");
        if (options.persist) {
          await persistSettings({ vaultPath: path });
        }
        return results;
      } catch (error) {
        const message = asErrorMessage(error, "Failed to list markdown files.");
        setListError(options.errorMessage ?? message);
        setListState("error");
        if (options.clearOnFailure) {
          setVaultPath(null);
          await persistSettings({ vaultPath: null });
        }
        return null;
      }
    },
    [persistSettings, showHiddenFolders],
  );

  const pickVault = useCallback(
    async (options?: PickOptions): Promise<VaultScanResults | null> => {
      setListError("");
      const selected = await open({
        directory: true,
        multiple: false,
        title: "Vault auswaehlen",
      });

      if (!selected || Array.isArray(selected)) {
        return null;
      }

      const snapshot = takeSnapshot();
      options?.onBeforeLoad?.();

      const errorMessage =
        options?.errorMessage ?? "Ausgewaehlter Vault ist nicht verfuegbar.";
      const results = await loadVault(selected, {
        persist: true,
        clearOnFailure: false,
        errorMessage,
      });

      if (!results) {
        restoreSnapshot(snapshot);
        setListError(errorMessage);
        options?.onLoadFailed?.();
      }

      return results;
    },
    [loadVault, restoreSnapshot, takeSnapshot],
  );

  const rescanVault = useCallback(async (): Promise<boolean> => {
    if (!vaultPath || listState === "loading") {
      return false;
    }
    setListError("");
    setListState("loading");
    try {
      const results = await invoke<VaultScanResults>("list_vault_entries", {
        vaultPath,
        showHiddenFolders,
      });
      setFiles(results.files);
      setFolders(results.folders);
      setLastRefreshAt(new Date().toISOString());
      setListState("idle");
      return true;
    } catch (error) {
      const message = asErrorMessage(error, "Vault konnte nicht neu gescannt werden.");
      setListError(message);
      setListState("error");
      return false;
    }
  }, [listState, showHiddenFolders, vaultPath]);

  useEffect(() => {
    if (!vaultPath || listState === "loading") {
      return;
    }
    if (lastRescanHiddenState.current === showHiddenFolders) {
      return;
    }
    lastRescanHiddenState.current = showHiddenFolders;
    void rescanVault();
  }, [listState, rescanVault, showHiddenFolders, vaultPath]);

  return {
    files,
    folders,
    listError,
    listState,
    lastRefreshAt,
    loadVault,
    pickVault,
    rescanVault,
    restoreSnapshot,
    setFiles,
    setFolders,
    setListError,
    setListState,
    setLastRefreshAt,
    setVaultPath,
    takeSnapshot,
    vaultPath,
  };
};

/**
 * @file apps/fmd-desktop/src/features/vault/useVaultPathInfo.ts
 *
 * Zweck:
 * - Stellt Pfad-Infos fuer Vaults bereit.
 */

import { useEffect, useMemo, useState } from "react";
import { invoke } from "@tauri-apps/api/core";

export type VaultPathInfo = {
  exists: boolean;
  isDir: boolean;
};

export const useVaultPathInfo = (paths: string[], isActive: boolean) => {
  const [infoByPath, setInfoByPath] = useState<Record<string, VaultPathInfo>>({});
  const pathsKey = useMemo(() => paths.join("|"), [paths]);

  useEffect(() => {
    if (!isActive) {
      return;
    }
    let cancelled = false;
    const load = async () => {
      if (paths.length === 0) {
        setInfoByPath({});
        return;
      }
      const entries = await Promise.all(
        paths.map(async (path) => {
          try {
            const info = await invoke<VaultPathInfo>("get_path_info", { path });
            return [path, info] as const;
          } catch {
            return [path, { exists: false, isDir: false }] as const;
          }
        }),
      );
      if (cancelled) {
        return;
      }
      const next: Record<string, VaultPathInfo> = {};
      entries.forEach(([path, info]) => {
        next[path] = info;
      });
      setInfoByPath(next);
    };
    void load();

    return () => {
      cancelled = true;
    };
  }, [isActive, paths, pathsKey]);

  return infoByPath;
};

/**
 * @file apps/fmd-desktop/src/keybindings/registerGlobalShortcuts.ts
 *
 * Zweck:
 * - Registriert globale Shortcuts und verbindet sie mit Actions.
 */

import {
  getEffectiveBinding,
  isEditableTarget,
  matchesBinding,
  type ShortcutPlatform,
  type ShortcutUserBindings,
} from "../lib/shortcuts/bindings";
import { type ShortcutCommand, getShortcutById } from "../lib/shortcuts/registry";
import {
  GLOBAL_SHORTCUT_HANDLERS,
  type GlobalShortcutContext,
  type GlobalShortcutHandler,
} from "./registry";

type ShortcutEntry = {
  command: ShortcutCommand;
  handler: GlobalShortcutHandler;
  binding: string | null;
};

type RegisterGlobalShortcutsOptions = {
  bindings: ShortcutUserBindings;
  platform: ShortcutPlatform;
  context: GlobalShortcutContext;
};

export const registerGlobalShortcuts = ({
  bindings,
  platform,
  context,
}: RegisterGlobalShortcutsOptions) => {
  const entries: ShortcutEntry[] = [];
  GLOBAL_SHORTCUT_HANDLERS.forEach((handler, commandId) => {
    const command = getShortcutById(commandId);
    if (!command) {
      return;
    }
    const binding = getEffectiveBinding(command, bindings, platform);
    entries.push({ command, handler, binding });
  });

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.defaultPrevented) {
      return;
    }
    const targetEditable = isEditableTarget(event.target);
    for (const entry of entries) {
      if (!entry.binding) {
        continue;
      }
      if (!entry.command.allowInTextInputs && targetEditable) {
        continue;
      }
      if (!matchesBinding(event, entry.binding)) {
        continue;
      }
      event.preventDefault();
      entry.handler(context);
      break;
    }
  };

  window.addEventListener("keydown", handleKeyDown);
  return () => window.removeEventListener("keydown", handleKeyDown);
};

