/**
 * @file apps/fmd-desktop/src/pages/exam-editor/components/ContentMode.tsx
 */

import type { ExamBlueprint } from "../../../features/exam-editor/types";
import type {
  ExamValidation,
  TaskValidation,
} from "../../../features/exam-editor/validation";
import { isCompositeTask } from "../../../features/exam-editor/validation";
import type { ExamEditorSelection } from "../types";
import { CardContentForm } from "./ContentForms";
import { HelpEditor } from "./HelpEditor";

const getTaskValidation = (
  validation: ExamValidation,
  taskId: string,
): TaskValidation | undefined =>
  validation.taskValidations.find((entry) => entry.taskId === taskId);

type ContentModeProps = {
  exam: ExamBlueprint;
  selection: ExamEditorSelection;
  validation: ExamValidation;
  onSelectTask: (taskId: string) => void;
  onTaskUpdate: (
    taskId: string,
    updates: { title?: string; helpText?: string; useCardWrapper?: boolean },
  ) => void;
  onCardUpdate: (
    taskId: string,
    cardId: string,
    updates: { prompt?: string; answer?: string; correct?: "true" | "false" | null },
  ) => void;
  onCardHelpChange: (taskId: string, cardId: string, value: string) => void;
  onOptionTextChange: (
    taskId: string,
    cardId: string,
    optionId: string,
    value: string,
  ) => void;
  onOptionToggle: (
    taskId: string,
    cardId: string,
    optionId: string,
    value: boolean,
  ) => void;
  onOptionSelect: (taskId: string, cardId: string, optionId: string) => void;
  onOptionAdd: (taskId: string, cardId: string) => void;
  onOptionRemove: (taskId: string, cardId: string, optionId: string) => void;
};

const resolveActiveTaskId = (
  exam: ExamBlueprint,
  selection: ExamEditorSelection,
) => {
  if (selection.type === "task") {
    return selection.taskId;
  }
  if (selection.type === "card") {
    return selection.taskId;
  }
  return exam.tasks[0]?.id ?? null;
};

export const ContentMode = ({
  exam,
  selection,
  validation,
  onSelectTask,
  onTaskUpdate,
  onCardUpdate,
  onCardHelpChange,
  onOptionTextChange,
  onOptionToggle,
  onOptionSelect,
  onOptionAdd,
  onOptionRemove,
}: ContentModeProps) => {
  const activeTaskId = resolveActiveTaskId(exam, selection);
  const activeTask = exam.tasks.find((task) => task.id === activeTaskId) ?? null;
  const orderedTasks = exam.tasks.slice().sort((a, b) => a.order - b.order);
  const taskValidation = activeTask
    ? getTaskValidation(validation, activeTask.id)
    : undefined;

  return (
    <div className="exam-editor-content">
      <aside className="panel exam-editor-panel content-nav">
        <header className="panel-header">
          <div>
            <h2>Tasks</h2>
            <p className="muted">Jump to a task to edit content.</p>
          </div>
        </header>
        <div className="panel-body">
          <ol className="content-task-list">
            {orderedTasks.map((task, index) => {
              const taskValidationEntry = getTaskValidation(validation, task.id);
              const isActive = task.id === activeTaskId;
              const isValid = taskValidationEntry?.valid ?? false;
              return (
                <li key={task.id} className={`content-task-item ${isActive ? "active" : ""}`}>
                  <button
                    type="button"
                    className="content-task-button"
                    onClick={() => onSelectTask(task.id)}
                  >
                    <span className={`status-dot ${isValid ? "valid" : "invalid"}`} />
                    <span className="task-label">Task {index + 1}</span>
                    <span className="task-title">{task.title.trim() || "Untitled"}</span>
                    <span className="card-count">{task.cards.length} card(s)</span>
                  </button>
                </li>
              );
            })}
          </ol>
        </div>
      </aside>

      <section className="panel exam-editor-panel content-editor">
        <header className="panel-header">
          <div>
            <h2>Content</h2>
            <p className="muted">Fill prompts, answers, and options.</p>
          </div>
        </header>
        <div className="panel-body">
          {!activeTask ? (
            <div className="exam-canvas-empty">
              <p>Create a task in Structure mode to start authoring.</p>
            </div>
          ) : (
            <div className="content-editor-body">
              <header className="content-task-header">
                <div>
                  <span className="eyebrow">Task</span>
                  <h3>{activeTask.title.trim() || "Untitled task"}</h3>
                </div>
                {isCompositeTask(activeTask) ? (
                  <div className="exam-task-warning">
                    Composite task: auto-grading can be unreliable.
                  </div>
                ) : null}
              </header>

              <label className="field">
                <span className="label">Task heading</span>
                <input
                  className="text-input"
                  value={activeTask.title}
                  onChange={(event) =>
                    onTaskUpdate(activeTask.id, { title: event.target.value })
                  }
                  placeholder="Optional heading"
                />
              </label>
              <HelpEditor
                label="Task help / hint"
                value={activeTask.helpText ?? ""}
                onChange={(value) => onTaskUpdate(activeTask.id, { helpText: value })}
                showPreviewToggle
              />

              {activeTask.cards.map((card, cardIndex) => {
                const cardValidation = taskValidation?.cardValidations?.[cardIndex];
                return (
                  <CardContentForm
                    key={card.id}
                    card={card}
                    validation={cardValidation}
                    onPromptChange={(value) =>
                      onCardUpdate(activeTask.id, card.id, { prompt: value })
                    }
                    onAnswerChange={(value) =>
                      onCardUpdate(activeTask.id, card.id, { answer: value })
                    }
                    onCorrectChange={(value) =>
                      onCardUpdate(activeTask.id, card.id, { correct: value })
                    }
                    onOptionTextChange={(optionId, value) =>
                      onOptionTextChange(activeTask.id, card.id, optionId, value)
                    }
                    onOptionToggle={(optionId, value) =>
                      onOptionToggle(activeTask.id, card.id, optionId, value)
                    }
                    onOptionSelect={(optionId) =>
                      onOptionSelect(activeTask.id, card.id, optionId)
                    }
                    onOptionAdd={() => onOptionAdd(activeTask.id, card.id)}
                    onOptionRemove={(optionId) =>
                      onOptionRemove(activeTask.id, card.id, optionId)
                    }
                    onHelpChange={(value) =>
                      onCardHelpChange(activeTask.id, card.id, value)
                    }
                  />
                );
              })}
              {taskValidation?.errors.length ? (
                <div className="error">{taskValidation.errors.join(" ")}</div>
              ) : null}
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

/**
 * @file apps/fmd-desktop/src/pages/exam-editor/components/ExamCanvas.tsx
 */

import {
  type DragEvent,
  type WheelEvent,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { AlertIcon, CheckIcon } from "../../../components/icons";
import type { ExamBlueprint, ExamTaskBlueprint, CardType } from "../../../features/exam-editor/types";
import type { ExamEditorSelection } from "../types";
import { serializeCardTypeLabel } from "../../../features/exam-editor/serializer";

const CARD_TYPES: CardType[] = ["qa", "tf", "m1", "m2", "cl", "cd", "cld"];

type ExamCanvasProps = {
  exam: ExamBlueprint;
  selection: ExamEditorSelection;
  validationSummary: { count: number; messages: string[] } | null;
  onSelectExam: () => void;
  onSelectTask: (taskId: string) => void;
  onSelectCard: (taskId: string, cardId: string) => void;
  onCanvasDrop: (cardType: CardType) => void;
  onTaskDrop: (taskId: string, cardType: CardType) => void;
  onReorderTask: (sourceIndex: number, targetIndex: number) => void;
  onDuplicateTask: (taskId: string) => void;
  onDeleteTask: (taskId: string) => void;
  onReorderCard: (taskId: string, sourceIndex: number, targetIndex: number) => void;
  onMoveCardAcrossTasks: (
    sourceTaskId: string,
    targetTaskId: string,
    sourceIndex: number,
    targetIndex: number,
  ) => void;
  onDeleteCard: (taskId: string, cardId: string) => void;
  showMoveButtons: boolean;
  getTaskWarning: (task: ExamTaskBlueprint) => string | null;
};

type DragPayload =
  | { kind: "task"; taskId: string }
  | { kind: "card"; taskId: string; cardId: string };

type TaskDropTarget = {
  taskId: string;
  position: "before" | "after";
};

type CardDropTarget = {
  taskId: string;
  cardId: string | null;
  position: "before" | "after";
};

const TASK_DRAG_TYPE = "application/x-fmd-task";
const CARD_DRAG_TYPE = "application/x-fmd-card";
const AUTO_SCROLL_EDGE = 48;
const AUTO_SCROLL_SPEED = 18;

const resolveDropType = (event: DragEvent<HTMLElement>) => {
  const value =
    event.dataTransfer.getData("application/x-fmd-card-type") ||
    event.dataTransfer.getData("text/plain");
  if (!value) {
    return null;
  }
  return CARD_TYPES.includes(value as CardType) ? (value as CardType) : null;
};

const allowDrop = (event: DragEvent<HTMLElement>) => {
  if (!event.dataTransfer.types.includes("application/x-fmd-card-type")) {
    return;
  }
  event.preventDefault();
  event.dataTransfer.dropEffect = "copy";
};

export const ExamCanvas = ({
  exam,
  selection,
  validationSummary,
  onSelectExam,
  onSelectTask,
  onSelectCard,
  onCanvasDrop,
  onTaskDrop,
  onReorderTask,
  onDuplicateTask,
  onDeleteTask,
  onReorderCard,
  onMoveCardAcrossTasks,
  onDeleteCard,
  showMoveButtons,
  getTaskWarning,
}: ExamCanvasProps) => {
  const [dragPayload, setDragPayload] = useState<DragPayload | null>(null);
  const [taskDropTarget, setTaskDropTarget] = useState<TaskDropTarget | null>(null);
  const [cardDropTarget, setCardDropTarget] = useState<CardDropTarget | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const dragPayloadRef = useRef<DragPayload | null>(null);
  const autoScrollFrameRef = useRef<number | null>(null);
  const autoScrollPointerRef = useRef<number | null>(null);
  const orderedTasks = useMemo(
    () => exam.tasks.slice().sort((a, b) => a.order - b.order),
    [exam.tasks],
  );
  const isExamSelected = selection.type === "exam";
  const hasValidationErrors = Boolean(
    validationSummary && validationSummary.count > 0,
  );
  const validationLabel = hasValidationErrors
    ? `Cannot save: ${validationSummary?.count ?? 0} validation ${
        validationSummary?.count === 1 ? "error" : "errors"
      }`
    : "All checks passed.";

  useEffect(() => {
    dragPayloadRef.current = dragPayload;
    if (!dragPayload) {
      autoScrollPointerRef.current = null;
      if (autoScrollFrameRef.current !== null) {
        window.cancelAnimationFrame(autoScrollFrameRef.current);
        autoScrollFrameRef.current = null;
      }
    }
  }, [dragPayload]);

  useEffect(() => {
    return () => {
      if (autoScrollFrameRef.current !== null) {
        window.cancelAnimationFrame(autoScrollFrameRef.current);
        autoScrollFrameRef.current = null;
      }
    };
  }, []);

  const clearDragState = () => {
    setDragPayload(null);
    setTaskDropTarget(null);
    setCardDropTarget(null);
  };

  const handleAutoScroll = (clientY: number) => {
    autoScrollPointerRef.current = clientY;
    if (autoScrollFrameRef.current !== null) {
      return;
    }
    const step = () => {
      const container = scrollContainerRef.current;
      const pointerY = autoScrollPointerRef.current;
      if (!container || pointerY === null || !dragPayloadRef.current) {
        autoScrollPointerRef.current = null;
        if (autoScrollFrameRef.current !== null) {
          window.cancelAnimationFrame(autoScrollFrameRef.current);
          autoScrollFrameRef.current = null;
        }
        return;
      }
      const rect = container.getBoundingClientRect();
      let delta = 0;
      if (pointerY < rect.top + AUTO_SCROLL_EDGE) {
        const distance = rect.top + AUTO_SCROLL_EDGE - pointerY;
        delta = -Math.min(
          AUTO_SCROLL_SPEED,
          (distance / AUTO_SCROLL_EDGE) * AUTO_SCROLL_SPEED,
        );
      } else if (pointerY > rect.bottom - AUTO_SCROLL_EDGE) {
        const distance = pointerY - (rect.bottom - AUTO_SCROLL_EDGE);
        delta = Math.min(
          AUTO_SCROLL_SPEED,
          (distance / AUTO_SCROLL_EDGE) * AUTO_SCROLL_SPEED,
        );
      }
      if (delta !== 0) {
        container.scrollTop += delta;
      }
      autoScrollFrameRef.current = window.requestAnimationFrame(step);
    };
    autoScrollFrameRef.current = window.requestAnimationFrame(step);
  };

  const handleCanvasDrop = (event: DragEvent<HTMLDivElement>) => {
    const cardType = resolveDropType(event);
    if (!cardType) {
      return;
    }
    event.preventDefault();
    onCanvasDrop(cardType);
  };

  const getDropPosition = (event: DragEvent<HTMLElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const midpoint = rect.top + rect.height / 2;
    return event.clientY <= midpoint ? "before" : "after";
  };

  const handleTaskDragStart = (event: DragEvent<HTMLDivElement>, taskId: string) => {
    const target = event.target as HTMLElement | null;
    if (target?.closest(".exam-task-actions")) {
      event.preventDefault();
      return;
    }
    event.dataTransfer.setData(TASK_DRAG_TYPE, taskId);
    event.dataTransfer.effectAllowed = "move";
    setDragPayload({ kind: "task", taskId });
  };

  const handleCardDragStart = (
    event: DragEvent<HTMLDivElement>,
    taskId: string,
    cardId: string,
  ) => {
    const target = event.target as HTMLElement | null;
    if (target?.closest(".exam-card-actions")) {
      event.preventDefault();
      return;
    }
    event.dataTransfer.setData(
      CARD_DRAG_TYPE,
      JSON.stringify({ taskId, cardId }),
    );
    event.dataTransfer.effectAllowed = "move";
    setDragPayload({ kind: "card", taskId, cardId });
  };

  const handleDragEnd = () => {
    clearDragState();
    autoScrollPointerRef.current = null;
    if (autoScrollFrameRef.current !== null) {
      window.cancelAnimationFrame(autoScrollFrameRef.current);
      autoScrollFrameRef.current = null;
    }
  };

  const handleTaskDragOver = (
    event: DragEvent<HTMLLIElement>,
    taskId: string,
    isEmpty: boolean,
  ) => {
    if (event.dataTransfer.types.includes("application/x-fmd-card-type")) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "copy";
      handleAutoScroll(event.clientY);
      return;
    }
    if (!dragPayload) {
      return;
    }
    if (dragPayload.kind === "task") {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      const position = getDropPosition(event);
      setTaskDropTarget({ taskId, position });
      handleAutoScroll(event.clientY);
      return;
    }
    if (dragPayload.kind === "card" && isEmpty) {
      event.preventDefault();
      event.dataTransfer.dropEffect = "move";
      setCardDropTarget({ taskId, cardId: null, position: "after" });
      handleAutoScroll(event.clientY);
    }
  };

  const handleTaskDrop = (event: DragEvent<HTMLLIElement>, taskId: string) => {
    const cardType = resolveDropType(event);
    if (cardType) {
      event.preventDefault();
      event.stopPropagation();
      onTaskDrop(taskId, cardType);
      clearDragState();
      return;
    }
    if (!dragPayload) {
      return;
    }
    if (dragPayload.kind === "card") {
      event.preventDefault();
      event.stopPropagation();
      const sourceTask = orderedTasks.find(
        (task) => task.id === dragPayload.taskId,
      );
      const targetTask = orderedTasks.find((task) => task.id === taskId);
      if (!sourceTask || !targetTask) {
        clearDragState();
        return;
      }
      if (targetTask.cards.length !== 0) {
        clearDragState();
        return;
      }
      const sourceIndex = sourceTask.cards.findIndex(
        (card) => card.id === dragPayload.cardId,
      );
      if (sourceIndex === -1) {
        clearDragState();
        return;
      }
      if (dragPayload.taskId === taskId) {
        clearDragState();
        return;
      }
      onMoveCardAcrossTasks(
        dragPayload.taskId,
        taskId,
        sourceIndex,
        0,
      );
      onSelectCard(taskId, dragPayload.cardId);
      clearDragState();
      return;
    }
    if (dragPayload.kind !== "task") {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const position = getDropPosition(event);
    const sourceIndex = orderedTasks.findIndex(
      (task) => task.id === dragPayload.taskId,
    );
    const targetIndex = orderedTasks.findIndex((task) => task.id === taskId);
    if (sourceIndex === -1 || targetIndex === -1) {
      clearDragState();
      return;
    }
    let insertIndex = position === "after" ? targetIndex + 1 : targetIndex;
    if (sourceIndex < insertIndex) {
      insertIndex -= 1;
    }
    if (insertIndex !== sourceIndex) {
      onReorderTask(sourceIndex, insertIndex);
    }
    clearDragState();
  };

  const handleCardDragOver = (
    event: DragEvent<HTMLDivElement>,
    taskId: string,
    cardId: string,
  ) => {
    if (!dragPayload || dragPayload.kind !== "card") {
      return;
    }
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    const position = getDropPosition(event);
    setCardDropTarget({ taskId, cardId, position });
    handleAutoScroll(event.clientY);
  };

  const handleCardListDragOver = (
    event: DragEvent<HTMLDivElement>,
    taskId: string,
  ) => {
    if (!dragPayload || dragPayload.kind !== "card") {
      return;
    }
    if (event.target !== event.currentTarget) {
      return;
    }
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    setCardDropTarget({ taskId, cardId: null, position: "after" });
    handleAutoScroll(event.clientY);
  };

  const handleCardDrop = (
    event: DragEvent<HTMLDivElement>,
    taskId: string,
    cardId: string,
  ) => {
    if (!dragPayload || dragPayload.kind !== "card") {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const sourceTask = orderedTasks.find(
      (entry) => entry.id === dragPayload.taskId,
    );
    const targetTask = orderedTasks.find((entry) => entry.id === taskId);
    if (!sourceTask || !targetTask) {
      clearDragState();
      return;
    }
    const sourceIndex = sourceTask.cards.findIndex(
      (card) => card.id === dragPayload.cardId,
    );
    const targetIndex = targetTask.cards.findIndex((card) => card.id === cardId);
    if (sourceIndex === -1 || targetIndex === -1) {
      clearDragState();
      return;
    }
    const position = getDropPosition(event);
    let insertIndex = position === "after" ? targetIndex + 1 : targetIndex;
    const sameTask = dragPayload.taskId === taskId;
    if (sameTask && sourceIndex < insertIndex) {
      insertIndex -= 1;
    }
    if (!sameTask || insertIndex !== sourceIndex) {
      if (sameTask) {
        onReorderCard(taskId, sourceIndex, insertIndex);
      } else {
        onMoveCardAcrossTasks(
          dragPayload.taskId,
          taskId,
          sourceIndex,
          insertIndex,
        );
      }
      onSelectCard(taskId, dragPayload.cardId);
    }
    clearDragState();
  };

  const handleCardListDrop = (
    event: DragEvent<HTMLDivElement>,
    taskId: string,
  ) => {
    if (!dragPayload || dragPayload.kind !== "card") {
      return;
    }
    if (event.target !== event.currentTarget) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    const sourceTask = orderedTasks.find(
      (entry) => entry.id === dragPayload.taskId,
    );
    const targetTask = orderedTasks.find((entry) => entry.id === taskId);
    if (!sourceTask || !targetTask) {
      clearDragState();
      return;
    }
    const sourceIndex = sourceTask.cards.findIndex(
      (card) => card.id === dragPayload.cardId,
    );
    if (sourceIndex === -1) {
      clearDragState();
      return;
    }
    if (dragPayload.taskId === taskId) {
      const insertIndex = Math.max(0, targetTask.cards.length - 1);
      if (insertIndex !== sourceIndex) {
        onReorderCard(taskId, sourceIndex, insertIndex);
      }
    } else {
      onMoveCardAcrossTasks(
        dragPayload.taskId,
        taskId,
        sourceIndex,
        targetTask.cards.length,
      );
    }
    onSelectCard(taskId, dragPayload.cardId);
    clearDragState();
  };

  const handleCanvasDragOver = (event: DragEvent<HTMLDivElement>) => {
    allowDrop(event);
    if (dragPayload) {
      handleAutoScroll(event.clientY);
    }
  };

  const handleCanvasWheel = (event: WheelEvent<HTMLDivElement>) => {
    if (!dragPayload) {
      return;
    }
    const container = scrollContainerRef.current;
    if (!container) {
      return;
    }
    container.scrollTop += event.deltaY;
    event.preventDefault();
  };

  const handleMoveTask = (taskId: string, direction: "up" | "down") => {
    const sourceIndex = orderedTasks.findIndex((task) => task.id === taskId);
    if (sourceIndex === -1) {
      return;
    }
    const targetIndex = direction === "up" ? sourceIndex - 1 : sourceIndex + 1;
    if (targetIndex < 0 || targetIndex >= orderedTasks.length) {
      return;
    }
    onReorderTask(sourceIndex, targetIndex);
    onSelectTask(taskId);
  };

  const handleMoveCard = (
    taskId: string,
    cardId: string,
    direction: "up" | "down",
  ) => {
    const task = orderedTasks.find((entry) => entry.id === taskId);
    if (!task) {
      return;
    }
    const sourceIndex = task.cards.findIndex((card) => card.id === cardId);
    if (sourceIndex === -1) {
      return;
    }
    const targetIndex = direction === "up" ? sourceIndex - 1 : sourceIndex + 1;
    if (targetIndex < 0 || targetIndex >= task.cards.length) {
      return;
    }
    onReorderCard(taskId, sourceIndex, targetIndex);
    onSelectCard(taskId, cardId);
  };

  return (
    <section
      className="panel exam-editor-panel exam-canvas"
      onDragOver={allowDrop}
      onDrop={handleCanvasDrop}
    >
      <header className="panel-header exam-canvas-header">
        <div>
          <h2>Canvas</h2>
          <p className="muted">Drop cards to create tasks and interactions.</p>
        </div>
        <div className="exam-canvas-status" role="status">
          <button
            type="button"
            className={`exam-canvas-status-button ${
              hasValidationErrors ? "is-invalid" : "is-valid"
            }`}
            aria-label={validationLabel}
          >
            {hasValidationErrors ? <AlertIcon /> : <CheckIcon />}
          </button>
          <div className="exam-canvas-status-tooltip" role="tooltip">
            <div className="exam-canvas-status-title">{validationLabel}</div>
            {hasValidationErrors ? (
              <ul className="exam-canvas-status-list">
                {validationSummary?.messages.map((message, index) => (
                  <li key={`${index}-${message}`}>{message}</li>
                ))}
              </ul>
            ) : null}
          </div>
        </div>
      </header>
      <div
        className="panel-body"
        ref={scrollContainerRef}
        onDragOver={handleCanvasDragOver}
        onWheel={handleCanvasWheel}
      >
        <button
          type="button"
          className={`exam-canvas-meta ${isExamSelected ? "selected" : ""}`}
          onClick={onSelectExam}
        >
          <span className="eyebrow">Exam</span>
          <strong>{exam.title.trim() || "Untitled exam"}</strong>
          <span className="muted">{exam.description.trim() || "No description"}</span>
        </button>

        {orderedTasks.length === 0 ? (
          <div className="exam-canvas-empty">
            <p>Drop a card type here to create Task 1.</p>
          </div>
        ) : (
          <ol className="exam-task-list">
            {orderedTasks.map((task, index) => {
              const isTaskSelected =
                selection.type === "task" && selection.taskId === task.id;
              const isTaskDragging =
                dragPayload?.kind === "task" && dragPayload.taskId === task.id;
              const taskDropPosition =
                taskDropTarget?.taskId === task.id
                  ? taskDropTarget.position
                  : null;
              const isCardDropTarget =
                dragPayload?.kind === "card" && cardDropTarget?.taskId === task.id;
              const warning = getTaskWarning(task);
              return (
                <li
                  key={task.id}
                  className={`exam-task-node ${isTaskSelected ? "selected" : ""}${
                    isTaskDragging ? " is-dragging" : ""
                  }${taskDropPosition ? " drop-target" : ""}${
                    taskDropPosition ? ` drop-${taskDropPosition}` : ""
                  }${isCardDropTarget ? " card-drop-target" : ""}`}
                  onDragOver={(event) =>
                    handleTaskDragOver(event, task.id, task.cards.length === 0)
                  }
                  onDrop={(event) => handleTaskDrop(event, task.id)}
                >
                  <div
                    className="exam-task-header"
                    draggable
                    onDragStart={(event) => handleTaskDragStart(event, task.id)}
                    onDragEnd={handleDragEnd}
                  >
                    <button
                      type="button"
                      className="exam-task-title"
                      onClick={() => onSelectTask(task.id)}
                    >
                      <span className="task-number">Task {index + 1}</span>
                      <span className="task-title-text">
                        {task.title.trim() || "Untitled task"}
                      </span>
                    </button>
                    <div className="exam-task-actions">
                      {showMoveButtons ? (
                        <>
                          <button
                            type="button"
                            className="ghost small"
                            onClick={() => handleMoveTask(task.id, "up")}
                            disabled={index === 0}
                          >
                            Up
                          </button>
                          <button
                            type="button"
                            className="ghost small"
                            onClick={() => handleMoveTask(task.id, "down")}
                            disabled={index === orderedTasks.length - 1}
                          >
                            Down
                          </button>
                        </>
                      ) : null}
                      <button
                        type="button"
                        className="ghost small"
                        onClick={() => onDuplicateTask(task.id)}
                      >
                        Duplicate
                      </button>
                      <button
                        type="button"
                        className="ghost small danger"
                        onClick={() => onDeleteTask(task.id)}
                      >
                        Delete
                      </button>
                    </div>
                  </div>
                  {warning ? <div className="exam-task-warning">{warning}</div> : null}
                  <div
                    className={`exam-card-list${
                      dragPayload?.kind === "card" &&
                      cardDropTarget?.taskId === task.id &&
                      cardDropTarget.cardId === null
                        ? " drop-target drop-after"
                        : ""
                    }`}
                    onDragOver={(event) => handleCardListDragOver(event, task.id)}
                    onDrop={(event) => handleCardListDrop(event, task.id)}
                  >
                    {task.cards.map((card, cardIndex) => {
                      const isCardSelected =
                        selection.type === "card" &&
                        selection.taskId === task.id &&
                        selection.cardId === card.id;
                      const isCardDragging =
                        dragPayload?.kind === "card" &&
                        dragPayload.taskId === task.id &&
                        dragPayload.cardId === card.id;
                      const cardDropPosition =
                        cardDropTarget?.taskId === task.id &&
                        cardDropTarget.cardId === card.id
                          ? cardDropTarget.position
                          : null;
                      return (
                        <div
                          key={card.id}
                          className={`exam-card-item ${
                            isCardSelected ? "selected" : ""
                          }${isCardDragging ? " is-dragging" : ""}${
                            cardDropPosition ? " drop-target" : ""
                          }${cardDropPosition ? ` drop-${cardDropPosition}` : ""}`}
                          draggable
                          onDragStart={(event) =>
                            handleCardDragStart(event, task.id, card.id)
                          }
                          onDragEnd={handleDragEnd}
                          onDragOver={(event) =>
                            handleCardDragOver(event, task.id, card.id)
                          }
                          onDrop={(event) =>
                            handleCardDrop(event, task.id, card.id)
                          }
                        >
                          <button
                            type="button"
                            className="exam-card-title"
                            onClick={() => onSelectCard(task.id, card.id)}
                          >
                            <span className="card-index">Card {cardIndex + 1}</span>
                            <span className="card-type">
                              {serializeCardTypeLabel(card.type)}
                            </span>
                            {card.helpText?.trim() ? (
                              <span className="card-hint">Hint</span>
                            ) : null}
                          </button>
                          <div className="exam-card-actions">
                            {showMoveButtons ? (
                              <>
                                <button
                                  type="button"
                                  className="ghost small"
                                  onClick={() =>
                                    handleMoveCard(task.id, card.id, "up")
                                  }
                                  disabled={cardIndex === 0}
                                >
                                  Up
                                </button>
                                <button
                                  type="button"
                                  className="ghost small"
                                  onClick={() =>
                                    handleMoveCard(task.id, card.id, "down")
                                  }
                                  disabled={cardIndex === task.cards.length - 1}
                                >
                                  Down
                                </button>
                              </>
                            ) : null}
                            <button
                              type="button"
                              className="ghost small danger"
                              onClick={() => onDeleteCard(task.id, card.id)}
                            >
                              Remove
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </li>
              );
            })}
          </ol>
        )}
      </div>
    </section>
  );
};

/**
 * @file apps/fmd-desktop/src/pages/exam-editor/components/HelpEditor.tsx
 */

import { useState } from "react";
import ReactMarkdown from "react-markdown";
import { AutoGrowTextarea } from "./AutoGrowTextarea";

type HelpEditorProps = {
  label: string;
  value: string;
  onChange: (value: string) => void;
  showPreviewToggle?: boolean;
};

export const HelpEditor = ({
  label,
  value,
  onChange,
  showPreviewToggle = false,
}: HelpEditorProps) => {
  const [showPreview, setShowPreview] = useState(false);
  const hasContent = value.trim().length > 0;

  return (
    <div className="help-editor">
      <div className="help-editor-header">
        <span className="label">{label}</span>
        <div className="help-editor-actions">
          {showPreviewToggle ? (
            <button
              type="button"
              className="ghost small"
              onClick={() => setShowPreview((prev) => !prev)}
              disabled={!hasContent}
            >
              {showPreview ? "Hide preview" : "Show preview"}
            </button>
          ) : null}
          <button
            type="button"
            className="ghost small"
            onClick={() => onChange("")}
            disabled={!hasContent}
          >
            Remove
          </button>
        </div>
      </div>
      <AutoGrowTextarea
        className="text-input exam-textarea"
        rows={4}
        value={value}
        placeholder="Write a markdown hint for this scope..."
        onChange={onChange}
      />
      {showPreviewToggle && showPreview && hasContent ? (
        <div className="help-preview">
          <ReactMarkdown>{value}</ReactMarkdown>
        </div>
      ) : null}
    </div>
  );
};

/**
 * @file apps/fmd-desktop/src/pages/exam-editor/components/PropertiesPanel.tsx
 */

import type { ExamBlueprint, CardType } from "../../../features/exam-editor/types";
import { serializeCardTypeLabel } from "../../../features/exam-editor/serializer";
import type { ExamEditorSelection } from "../types";
import { HelpEditor } from "./HelpEditor";

const CARD_TYPES: CardType[] = ["qa", "tf", "m1", "m2", "cl", "cd", "cld"];

type PropertiesPanelProps = {
  exam: ExamBlueprint;
  selection: ExamEditorSelection;
  onExamUpdate: (updates: Pick<ExamBlueprint, "title" | "description">) => void;
  onTaskUpdate: (
    taskId: string,
    updates: { title?: string; helpText?: string; useCardWrapper?: boolean },
  ) => void;
  onCardUpdate: (taskId: string, cardId: string, updates: { helpText?: string }) => void;
  onCardTypeChange: (taskId: string, cardId: string, type: CardType) => void;
};

export const PropertiesPanel = ({
  exam,
  selection,
  onExamUpdate,
  onTaskUpdate,
  onCardUpdate,
  onCardTypeChange,
}: PropertiesPanelProps) => {
  if (selection.type === "task") {
    const task = exam.tasks.find((entry) => entry.id === selection.taskId);
    if (!task) {
      return null;
    }
    return (
      <aside className="panel exam-editor-panel properties-panel">
        <header className="panel-header">
          <div>
            <h2>Task properties</h2>
            <p className="muted">Edit task title and hints.</p>
          </div>
        </header>
        <div className="panel-body">
          <label className="field">
            <span className="label">Task heading</span>
            <input
              className="text-input"
              value={task.title}
              onChange={(event) =>
                onTaskUpdate(task.id, { title: event.target.value })
              }
              placeholder="Optional heading"
            />
          </label>
          <div className="field">
            <span className="label">Card wrapper</span>
            <label className="choice-pill">
              <input
                type="checkbox"
                checked={task.useCardWrapper}
                onChange={(event) =>
                  onTaskUpdate(task.id, { useCardWrapper: event.target.checked })
                }
              />
              Wrap task in #card block
            </label>
            <span className="muted small">
              Applies to the full task, including all parts.
            </span>
          </div>
          <HelpEditor
            label="Task help / hint"
            value={task.helpText ?? ""}
            onChange={(value) => onTaskUpdate(task.id, { helpText: value })}
          />
        </div>
      </aside>
    );
  }

  if (selection.type === "card") {
    const task = exam.tasks.find((entry) => entry.id === selection.taskId);
    const card = task?.cards.find((entry) => entry.id === selection.cardId);
    if (!task || !card) {
      return null;
    }
    return (
      <aside className="panel exam-editor-panel properties-panel">
        <header className="panel-header">
          <div>
            <h2>Card properties</h2>
            <p className="muted">Configure type and hints.</p>
          </div>
        </header>
        <div className="panel-body">
          <label className="field">
            <span className="label">Card type</span>
            <select
              className="text-input"
              value={card.type}
              onChange={(event) =>
                onCardTypeChange(task.id, card.id, event.target.value as CardType)
              }
            >
              {CARD_TYPES.map((type) => (
                <option key={type} value={type}>
                  {serializeCardTypeLabel(type)}
                </option>
              ))}
            </select>
            <span className="muted small">
              Changing the type resets card-specific content.
            </span>
          </label>
          <HelpEditor
            label="Card help / hint"
            value={card.helpText ?? ""}
            onChange={(value) => onCardUpdate(task.id, card.id, { helpText: value })}
          />
        </div>
      </aside>
    );
  }

  return (
    <aside className="panel exam-editor-panel properties-panel">
      <header className="panel-header">
        <div>
          <h2>Exam properties</h2>
          <p className="muted">Define title and description.</p>
        </div>
      </header>
      <div className="panel-body">
        <label className="field">
          <span className="label">Title</span>
          <input
            className="text-input"
            value={exam.title}
            onChange={(event) =>
              onExamUpdate({
                title: event.target.value,
                description: exam.description,
              })
            }
            placeholder="Exam title"
          />
        </label>
        <label className="field">
          <span className="label">Description</span>
          <textarea
            className="text-input exam-textarea"
            rows={4}
            value={exam.description}
            onChange={(event) =>
              onExamUpdate({
                title: exam.title,
                description: event.target.value,
              })
            }
            placeholder="Short description"
          />
        </label>
      </div>
    </aside>
  );
};

/**
 * @file apps/fmd-desktop/src/pages/exam-editor/ExamEditorView.tsx
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { save } from "@tauri-apps/plugin-dialog";
import { asErrorMessage } from "../../lib/errors";
import { joinPath, normalizeRelativePath, normalizeVaultPath } from "../../lib/path";
import { type VaultFile } from "../../lib/tree";
import {
  cloneTaskBlueprint,
  createCardBlueprint,
  createChoiceOption,
  createExamBlueprint,
  createTaskBlueprint,
  reorderCardsByIndex,
  reorderTasksByIndex,
} from "../../features/exam-editor/blueprint";
import type {
  CardType,
  ExamBlueprint,
  ExamTaskBlueprint,
} from "../../features/exam-editor/types";
import {
  serializeCardTypeLabel,
  serializeExamBlueprint,
} from "../../features/exam-editor/serializer";
import { isCompositeTask, validateExamBlueprint } from "../../features/exam-editor/validation";
import { importExamMarkdown, isExamMarkdown } from "../../features/exam-editor/importer";
import { findNextNewExamFilename } from "../../features/exam-editor/fileNaming";
import { CardPalette } from "./components/CardPalette";
import { ExamCanvas } from "./components/ExamCanvas";
import { PropertiesPanel } from "./components/PropertiesPanel";
import { ContentMode } from "./components/ContentMode";
import type {
  ExamEditorControlsState,
  ExamEditorMode,
  ExamEditorSelection,
} from "./types";

const normalizeTaskOrder = (tasks: ExamTaskBlueprint[]) =>
  tasks.map((task, index) => ({ ...task, order: index }));

type SaveState = "idle" | "saving" | "saved";

type ExamEditorViewProps = {
  sourcePath?: string | null;
  sourceRelativePath?: string | null;
  sourceMarkdown?: string;
  activeFolderPath?: string | null;
  vaultFiles?: VaultFile[];
  vaultPath?: string | null;
  showMoveButtons?: boolean;
  onControlsReady?: (controls: ExamEditorControlsState | null) => void;
  onSave?: (payload: { path: string; markdown: string }) => void;
};

const isPathInsideVault = (path: string, vaultPath: string | null) => {
  if (!vaultPath) {
    return false;
  }
  const normalizedVault = normalizeVaultPath(vaultPath);
  const normalizedPath = normalizeVaultPath(path);
  if (!normalizedVault || !normalizedPath) {
    return false;
  }
  return (
    normalizedPath === normalizedVault ||
    normalizedPath.startsWith(`${normalizedVault}/`)
  );
};

const isAbsolutePath = (value: string) => /^(?:[A-Za-z]:[\\/]|\/)/.test(value);

const normalizeFolderPath = (value: string | null | undefined) =>
  normalizeRelativePath(value ?? "").replace(/\/+$/, "");

const getParentRelativePath = (value: string) => {
  const normalized = normalizeRelativePath(value).replace(/\/+$/, "");
  const lastSlash = normalized.lastIndexOf("/");
  if (lastSlash <= 0) {
    return "";
  }
  return normalized.slice(0, lastSlash);
};

const isEditableTarget = (target: EventTarget | null) => {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  if (target.isContentEditable) {
    return true;
  }
  const tag = target.tagName.toLowerCase();
  if (tag === "input" || tag === "textarea" || tag === "select") {
    return true;
  }
  return Boolean(
    target.closest('[contenteditable="true"], [contenteditable=""], [role="textbox"]'),
  );
};

const isModalOpen = () => {
  if (typeof document === "undefined") {
    return false;
  }
  return Boolean(
    document.querySelector(".modal-backdrop, .context-menu-backdrop"),
  );
};

export const ExamEditorView = ({
  sourcePath,
  sourceRelativePath,
  sourceMarkdown,
  activeFolderPath,
  vaultFiles,
  vaultPath,
  showMoveButtons,
  onControlsReady,
  onSave,
}: ExamEditorViewProps) => {
  const [exam, setExam] = useState<ExamBlueprint>(() => createExamBlueprint());
  const [selection, setSelection] = useState<ExamEditorSelection>({ type: "exam" });
  const [mode, setMode] = useState<ExamEditorMode>("structure");
  const [savePath, setSavePath] = useState<string | null>(null);
  const [saveState, setSaveState] = useState<SaveState>("idle");
  const [saveError, setSaveError] = useState("");
  const [lastSavedContent, setLastSavedContent] = useState<string | null>(null);
  const [importMessage, setImportMessage] = useState("");
  const [importWarnings, setImportWarnings] = useState<string[]>([]);
  const lastLoadedRef = useRef<{ path: string | null; markdown: string | null }>({
    path: null,
    markdown: null,
  });
  const lastVaultPathRef = useRef<string | null>(vaultPath ?? null);

  const validation = useMemo(() => validateExamBlueprint(exam), [exam]);
  const canSave = validation.valid;
  const isSaving = saveState === "saving";
  const markdown = useMemo(() => serializeExamBlueprint(exam), [exam]);
  const validationSummary = useMemo(() => {
    if (validation.valid) {
      return null;
    }
    const ordered = exam.tasks.slice().sort((a, b) => a.order - b.order);
    const taskLookup = new Map(
      ordered.map((task, index) => [task.id, { task, index }]),
    );
    const messages: string[] = [];
    validation.errors.forEach((error) => {
      messages.push(error);
    });
    validation.taskValidations.forEach((taskValidation) => {
      const info = taskLookup.get(taskValidation.taskId);
      const taskIndex = info ? info.index + 1 : null;
      const taskLabel = taskIndex ? `Task ${taskIndex}` : "Task";
      taskValidation.errors.forEach((error) => {
        messages.push(`${taskLabel}: ${error}`);
      });
      const cards = info?.task.cards ?? [];
      taskValidation.cardValidations.forEach((cardValidation, cardIndex) => {
        if (cardValidation.errors.length === 0) {
          return;
        }
        const card = cards[cardIndex];
        const cardLabel = card ? serializeCardTypeLabel(card.type) : "Card";
        const partLabel = `Part ${cardIndex + 1} (${cardLabel})`;
        const location = taskIndex ? `${taskLabel} -> ${partLabel}` : partLabel;
        cardValidation.errors.forEach((error) => {
          messages.push(`${location}: ${error}`);
        });
      });
    });
    if (messages.length === 0) {
      messages.push("Validation failed.");
    }
    return {
      count: messages.length,
      messages: messages.slice(0, 3),
    };
  }, [exam.tasks, validation]);

  const updateTasks = useCallback(
    (updater: (tasks: ExamTaskBlueprint[]) => ExamTaskBlueprint[]) => {
      setExam((prev) => {
        const nextTasks = normalizeTaskOrder(updater(prev.tasks));
        return { ...prev, tasks: nextTasks };
      });
    },
    [],
  );

  const handleExamUpdate = useCallback(
    (updates: Pick<ExamBlueprint, "title" | "description">) => {
      setExam((prev) => ({ ...prev, ...updates }));
    },
    [],
  );

  const handleTaskUpdate = useCallback(
    (
      taskId: string,
      updates: { title?: string; helpText?: string; useCardWrapper?: boolean },
    ) => {
      updateTasks((tasks) =>
        tasks.map((task) =>
          task.id === taskId ? { ...task, ...updates } : task,
        ),
      );
    },
    [updateTasks],
  );

  const handleCardUpdate = useCallback(
    (
      taskId: string,
      cardId: string,
      updates: { prompt?: string; answer?: string; correct?: "true" | "false" | null; helpText?: string },
    ) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          return {
            ...task,
            cards: task.cards.map((card) =>
              card.id === cardId ? { ...card, ...updates } : card,
            ),
          };
        }),
      );
    },
    [updateTasks],
  );

  const handleCardTypeChange = useCallback(
    (taskId: string, cardId: string, type: CardType) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId) {
              return card;
            }
            const nextCard = createCardBlueprint(type);
            nextCard.helpText = card.helpText;
            if ("prompt" in card && "prompt" in nextCard) {
              nextCard.prompt = card.prompt;
            }
            return nextCard;
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleAddTask = useCallback(
    (cardType: CardType) => {
      const newTask = createTaskBlueprint(exam.tasks.length, cardType);
      updateTasks((tasks) => [...tasks, newTask]);
      setSelection({
        type: "card",
        taskId: newTask.id,
        cardId: newTask.cards[0]?.id ?? newTask.id,
      });
    },
    [exam.tasks.length, updateTasks],
  );

  const handleAddCardToTask = useCallback(
    (taskId: string, cardType: CardType) => {
      const newCard = createCardBlueprint(cardType);
      updateTasks((tasks) =>
        tasks.map((task) =>
          task.id === taskId
            ? { ...task, cards: [...task.cards, newCard] }
            : task,
        ),
      );
      setSelection({ type: "card", taskId, cardId: newCard.id });
    },
    [updateTasks],
  );

  const handleReorderTask = useCallback(
    (sourceIndex: number, targetIndex: number) => {
      updateTasks((tasks) => reorderTasksByIndex(tasks, sourceIndex, targetIndex));
    },
    [updateTasks],
  );

  const handleDuplicateTask = useCallback(
    (taskId: string) => {
      const task = exam.tasks.find((entry) => entry.id === taskId);
      if (!task) {
        return;
      }
      const clonedTask = cloneTaskBlueprint(task);
      updateTasks((tasks) => {
        const index = tasks.findIndex((entry) => entry.id === taskId);
        if (index === -1) {
          return tasks;
        }
        const next = [...tasks];
        next.splice(index + 1, 0, clonedTask);
        return next;
      });
      setSelection({ type: "task", taskId: clonedTask.id });
    },
    [exam.tasks, updateTasks],
  );

  const handleDeleteTask = useCallback(
    (taskId: string) => {
      updateTasks((tasks) => tasks.filter((task) => task.id !== taskId));
      setSelection({ type: "exam" });
    },
    [updateTasks],
  );

  const handleReorderCard = useCallback(
    (taskId: string, sourceIndex: number, targetIndex: number) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          return {
            ...task,
            cards: reorderCardsByIndex(task.cards, sourceIndex, targetIndex),
          };
        }),
      );
    },
    [updateTasks],
  );

  const handleMoveCardAcrossTasks = useCallback(
    (
      sourceTaskId: string,
      targetTaskId: string,
      sourceIndex: number,
      targetIndex: number,
    ) => {
      if (sourceTaskId === targetTaskId) {
        handleReorderCard(sourceTaskId, sourceIndex, targetIndex);
        return;
      }
      updateTasks((tasks) => {
        const sourceTask = tasks.find((task) => task.id === sourceTaskId);
        const targetTask = tasks.find((task) => task.id === targetTaskId);
        if (!sourceTask || !targetTask) {
          return tasks;
        }
        if (sourceIndex < 0 || sourceIndex >= sourceTask.cards.length) {
          return tasks;
        }
        const movedCard = sourceTask.cards[sourceIndex];
        const nextTasks = tasks.flatMap((task) => {
          if (task.id !== sourceTaskId) {
            return [task];
          }
          const nextCards = task.cards.filter(
            (_, index) => index !== sourceIndex,
          );
          if (nextCards.length === 0) {
            return [];
          }
          return [{ ...task, cards: nextCards }];
        });
        return nextTasks.map((task) => {
          if (task.id !== targetTaskId) {
            return task;
          }
          const nextCards = task.cards.slice();
          const insertIndex = Math.max(0, Math.min(targetIndex, nextCards.length));
          nextCards.splice(insertIndex, 0, movedCard);
          return { ...task, cards: nextCards };
        });
      });
    },
    [handleReorderCard, updateTasks],
  );

  const handleDeleteCard = useCallback(
    (taskId: string, cardId: string) => {
      updateTasks((tasks) =>
        tasks.flatMap((task) => {
          if (task.id !== taskId) {
            return [task];
          }
          const nextCards = task.cards.filter((card) => card.id !== cardId);
          if (nextCards.length === 0) {
            return [];
          }
          return [{ ...task, cards: nextCards }];
        }),
      );
    },
    [updateTasks],
  );

  const handleOptionTextChange = useCallback(
    (taskId: string, cardId: string, optionId: string, value: string) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId || (card.type !== "m1" && card.type !== "m2")) {
              return card;
            }
            return {
              ...card,
              options: card.options.map((option) =>
                option.id === optionId ? { ...option, text: value } : option,
              ),
            };
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleOptionToggle = useCallback(
    (taskId: string, cardId: string, optionId: string, value: boolean) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId || (card.type !== "m1" && card.type !== "m2")) {
              return card;
            }
            return {
              ...card,
              options: card.options.map((option) =>
                option.id === optionId ? { ...option, isCorrect: value } : option,
              ),
            };
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleOptionSelect = useCallback(
    (taskId: string, cardId: string, optionId: string) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId || (card.type !== "m1" && card.type !== "m2")) {
              return card;
            }
            return {
              ...card,
              options: card.options.map((option) => ({
                ...option,
                isCorrect: option.id === optionId,
              })),
            };
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleOptionAdd = useCallback(
    (taskId: string, cardId: string) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId || (card.type !== "m1" && card.type !== "m2")) {
              return card;
            }
            return {
              ...card,
              options: [...card.options, createChoiceOption()],
            };
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleOptionRemove = useCallback(
    (taskId: string, cardId: string, optionId: string) => {
      updateTasks((tasks) =>
        tasks.map((task) => {
          if (task.id !== taskId) {
            return task;
          }
          const cards = task.cards.map((card) => {
            if (card.id !== cardId || (card.type !== "m1" && card.type !== "m2")) {
              return card;
            }
            return {
              ...card,
              options: card.options.filter((option) => option.id !== optionId),
            };
          });
          return { ...task, cards };
        }),
      );
    },
    [updateTasks],
  );

  const handleCardHelpChange = useCallback(
    (taskId: string, cardId: string, value: string) => {
      handleCardUpdate(taskId, cardId, { helpText: value });
    },
    [handleCardUpdate],
  );

  const handleNewExam = useCallback(async () => {
    setSaveError("");
    setImportMessage("");
    setImportWarnings([]);
    setSaveState("idle");

    if (!vaultPath) {
      setSaveError("No active vault selected.");
      return;
    }

    const targetRelativeDir = sourceRelativePath
      ? getParentRelativePath(sourceRelativePath)
      : normalizeFolderPath(activeFolderPath);
    const existingRelativePaths = vaultFiles?.map((file) => file.relative_path) ?? [];
    const nextFilename = findNextNewExamFilename(
      targetRelativeDir,
      existingRelativePaths,
    );

    if (!nextFilename) {
      setSaveError("All New Exam filenames (01-99) already exist in this folder.");
      return;
    }

    const targetPath = joinPath(vaultPath, targetRelativeDir, nextFilename);
    const nextExam = createExamBlueprint();
    const initialMarkdown = serializeExamBlueprint(nextExam);

    setSaveState("saving");
    try {
      await invoke("write_text_file", {
        path: targetPath,
        contents: initialMarkdown,
      });
      setExam(nextExam);
      setSelection({ type: "exam" });
      setSavePath(targetPath);
      setSaveState("saved");
      setLastSavedContent(initialMarkdown);
      onSave?.({ path: targetPath, markdown: initialMarkdown });
    } catch (error) {
      setSaveError(asErrorMessage(error, "Failed to create new exam file."));
      setSaveState("idle");
    }
  }, [
    activeFolderPath,
    onSave,
    sourceRelativePath,
    vaultFiles,
    vaultPath,
  ]);

  const handleSave = useCallback(
    async (forceDialog = false) => {
      const currentValidation = validateExamBlueprint(exam);
      if (!currentValidation.valid) {
        setSaveState("idle");
        return;
      }
      setSaveState("saving");
      setSaveError("");
      try {
        const resolvePath = (path: string) =>
          vaultPath && !isAbsolutePath(path) ? joinPath(vaultPath, path) : path;
        let targetPath = savePath;
        let nextSavePath = savePath;
        if (!targetPath || forceDialog) {
          const suggestedName = exam.title.trim()
            ? `${exam.title.trim()}.md`
            : "New Exam.md";
          const defaultPath =
            savePath && isPathInsideVault(savePath, vaultPath ?? null)
              ? savePath
              : vaultPath
                ? joinPath(vaultPath, suggestedName)
                : suggestedName;
          const chosenPath = await save({
            defaultPath,
            filters: [{ name: "Markdown", extensions: ["md"] }],
          });
          if (!chosenPath) {
            setSaveState("idle");
            return;
          }
          targetPath = resolvePath(chosenPath);
          nextSavePath = targetPath;
        } else {
          targetPath = resolvePath(targetPath);
          nextSavePath = targetPath;
        }

        await invoke("write_text_file", {
          path: targetPath,
          contents: markdown,
        });
        setSavePath(nextSavePath ?? targetPath);
        setSaveState("saved");
        setLastSavedContent(markdown);
        onSave?.({ path: targetPath, markdown });
      } catch (error) {
        setSaveError(asErrorMessage(error, "Failed to save exam."));
        setSaveState("idle");
      }
    },
    [exam, exam.title, markdown, onSave, savePath, vaultPath],
  );

  const controls = useMemo<ExamEditorControlsState>(
    () => ({
      mode,
      canSave,
      isSaving,
      savePath,
      saveState,
      validationSummary,
      onModeChange: setMode,
      onNewExam: handleNewExam,
      onSaveAs: () => handleSave(true),
      onSave: () => handleSave(false),
    }),
    [
      canSave,
      handleNewExam,
      handleSave,
      isSaving,
      mode,
      savePath,
      saveState,
      validationSummary,
    ],
  );

  const orderedTasks = useMemo(
    () => exam.tasks.slice().sort((a, b) => a.order - b.order),
    [exam.tasks],
  );

  const handleKeyboardReorder = useCallback(
    (direction: "up" | "down") => {
      const delta = direction === "up" ? -1 : 1;
      if (selection.type === "task") {
        const sourceIndex = orderedTasks.findIndex(
          (task) => task.id === selection.taskId,
        );
        if (sourceIndex === -1) {
          return false;
        }
        const targetIndex = sourceIndex + delta;
        if (targetIndex < 0 || targetIndex >= orderedTasks.length) {
          return false;
        }
        handleReorderTask(sourceIndex, targetIndex);
        return true;
      }
      if (selection.type === "card") {
        const task = exam.tasks.find((entry) => entry.id === selection.taskId);
        if (!task) {
          return false;
        }
        const sourceIndex = task.cards.findIndex(
          (card) => card.id === selection.cardId,
        );
        if (sourceIndex === -1) {
          return false;
        }
        const targetIndex = sourceIndex + delta;
        if (targetIndex < 0 || targetIndex >= task.cards.length) {
          return false;
        }
        handleReorderCard(task.id, sourceIndex, targetIndex);
        return true;
      }
      return false;
    },
    [exam.tasks, handleReorderCard, handleReorderTask, orderedTasks, selection],
  );

  useEffect(() => {
    if (!onControlsReady) {
      return;
    }
    onControlsReady(controls);
  }, [controls, onControlsReady]);

  useEffect(() => {
    return () => {
      onControlsReady?.(null);
    };
  }, [onControlsReady]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented) {
        return;
      }
      if (isModalOpen()) {
        return;
      }
      const isSaveShortcut =
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "s";
      if (isSaveShortcut) {
        event.preventDefault();
        void handleSave(false);
        return;
      }
      if (event.key === "ArrowUp" || event.key === "ArrowDown") {
        if (mode !== "structure") {
          return;
        }
        if (isEditableTarget(event.target)) {
          return;
        }
        const moved = handleKeyboardReorder(
          event.key === "ArrowUp" ? "up" : "down",
        );
        if (moved) {
          event.preventDefault();
        }
        return;
      }
      if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
        if (isEditableTarget(event.target)) {
          return;
        }
        const nextMode = event.key === "ArrowLeft" ? "structure" : "content";
        if (mode !== nextMode) {
          setMode(nextMode);
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [handleKeyboardReorder, handleSave, mode]);

  useEffect(() => {
    if (selection.type === "task") {
      const exists = exam.tasks.some((task) => task.id === selection.taskId);
      if (!exists) {
        setSelection({ type: "exam" });
      }
    }
    if (selection.type === "card") {
      const task = exam.tasks.find((entry) => entry.id === selection.taskId);
      if (!task) {
        setSelection({ type: "exam" });
        return;
      }
      const cardExists = task.cards.some((card) => card.id === selection.cardId);
      if (!cardExists) {
        setSelection({ type: "task", taskId: task.id });
      }
    }
  }, [exam.tasks, selection]);

  useEffect(() => {
    if (saveState !== "saved" || !lastSavedContent) {
      return;
    }
    if (markdown !== lastSavedContent) {
      setSaveState("idle");
    }
  }, [lastSavedContent, markdown, saveState]);

  useEffect(() => {
    if (lastVaultPathRef.current === vaultPath) {
      return;
    }
    lastVaultPathRef.current = vaultPath ?? null;
    if (!savePath) {
      return;
    }
    if (vaultPath && isPathInsideVault(savePath, vaultPath)) {
      return;
    }
    setSavePath(null);
    setSaveState("idle");
    setLastSavedContent(null);
  }, [savePath, vaultPath]);

  useEffect(() => {
    if (sourcePath === undefined || sourceMarkdown === undefined) {
      return;
    }
    const lastLoaded = lastLoadedRef.current;
    if (
      lastLoaded.path === sourcePath &&
      lastLoaded.markdown === sourceMarkdown
    ) {
      return;
    }
    if (
      sourcePath &&
      savePath &&
      sourcePath === savePath &&
      lastSavedContent === sourceMarkdown
    ) {
      return;
    }
    lastLoadedRef.current = { path: sourcePath ?? null, markdown: sourceMarkdown };
    setImportWarnings([]);
    setImportMessage("");
    setSaveState("idle");
    setSaveError("");

    if (!sourcePath) {
      return;
    }
    if (!sourceMarkdown.trim()) {
      const blankExam = createExamBlueprint();
      setExam(blankExam);
      setSelection({ type: "exam" });
      setSavePath(sourcePath);
      setLastSavedContent(sourceMarkdown);
      return;
    }
    if (!isExamMarkdown(sourceMarkdown)) {
      setImportMessage(
        "Selected file has no #exam block. Create a new exam or switch back to Markdown.",
      );
      setExam(createExamBlueprint());
      setSelection({ type: "exam" });
      setSavePath(null);
      setLastSavedContent(null);
      return;
    }
    const imported = importExamMarkdown(sourceMarkdown);
    if (!imported) {
      setImportMessage("Unable to import exam data from this file.");
      setExam(createExamBlueprint());
      setSelection({ type: "exam" });
      setSavePath(null);
      setLastSavedContent(null);
      return;
    }
    setExam(imported.blueprint);
    setSelection({ type: "exam" });
    setImportWarnings(imported.warnings);
    setSavePath(sourcePath);
    setLastSavedContent(sourceMarkdown);
  }, [lastSavedContent, savePath, sourceMarkdown, sourcePath]);

  const getTaskWarning = useCallback(
    (task: ExamTaskBlueprint) =>
      isCompositeTask(task) ? "Composite task: auto-grading can be unreliable." : null,
    [],
  );

  return (
    <div className="exam-editor-page">
      {mode === "structure" ? (
        <div className="exam-editor-structure">
          <CardPalette onQuickAdd={handleAddTask} />
          {importMessage ? <div className="error">{importMessage}</div> : null}
          {importWarnings.length > 0 ? (
            <div className="exam-task-warning">
              {importWarnings.map((warning) => (
                <div key={warning}>{warning}</div>
              ))}
            </div>
          ) : null}
          {saveError ? <div className="error">{saveError}</div> : null}
          <div className="exam-editor-layout">
            <PropertiesPanel
              exam={exam}
              selection={selection}
              onExamUpdate={handleExamUpdate}
              onTaskUpdate={handleTaskUpdate}
              onCardUpdate={(taskId, cardId, updates) =>
                handleCardUpdate(taskId, cardId, updates)
              }
              onCardTypeChange={handleCardTypeChange}
            />
            <ExamCanvas
              exam={exam}
              selection={selection}
              validationSummary={validationSummary}
              onSelectExam={() => setSelection({ type: "exam" })}
              onSelectTask={(taskId) => setSelection({ type: "task", taskId })}
              onSelectCard={(taskId, cardId) =>
                setSelection({ type: "card", taskId, cardId })
              }
              onCanvasDrop={handleAddTask}
              onTaskDrop={handleAddCardToTask}
              onReorderTask={handleReorderTask}
              onDuplicateTask={handleDuplicateTask}
              onDeleteTask={handleDeleteTask}
              onReorderCard={handleReorderCard}
              onMoveCardAcrossTasks={handleMoveCardAcrossTasks}
              onDeleteCard={handleDeleteCard}
              showMoveButtons={Boolean(showMoveButtons)}
              getTaskWarning={getTaskWarning}
            />
          </div>
        </div>
      ) : (
        <>
          {importMessage ? <div className="error">{importMessage}</div> : null}
          {importWarnings.length > 0 ? (
            <div className="exam-task-warning">
              {importWarnings.map((warning) => (
                <div key={warning}>{warning}</div>
              ))}
            </div>
          ) : null}
          {saveError ? <div className="error">{saveError}</div> : null}
          <ContentMode
            exam={exam}
            selection={selection}
            validation={validation}
            onSelectTask={(taskId) => setSelection({ type: "task", taskId })}
            onTaskUpdate={handleTaskUpdate}
            onCardUpdate={(taskId, cardId, updates) =>
              handleCardUpdate(taskId, cardId, updates)
            }
            onCardHelpChange={handleCardHelpChange}
            onOptionTextChange={handleOptionTextChange}
            onOptionToggle={handleOptionToggle}
            onOptionSelect={handleOptionSelect}
            onOptionAdd={handleOptionAdd}
            onOptionRemove={handleOptionRemove}
          />
        </>
      )}
    </div>
  );
};

