  const [overviewTab, setOverviewTab] = useState<"ready" | "statistics">("ready");
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [deleteConfirmInput, setDeleteConfirmInput] = useState("");
