 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer preview.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

.file-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.file-item {
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--accent-weak-bg);
  border: 1px solid transparent;
  cursor: pointer;
  transition: 0.2s ease;
}

.file-item:hover {
  border-color: var(--accent-border);
}

.file-item.active {
  border-color: var(--accent-border);
  background: var(--accent-active-bg);
}

.file-name {
  font-size: 0.9rem;
  color: var(--ink);
}

.file-item .inline-rename-input {
  font-size: 0.9rem;
}

.preview {
  margin: 0;
  padding: 16px;
  background-color: var(--md-question-bg, var(--md-surface-bg));
  color: var(--preview-ink);
  border-radius: 16px;
  flex: 1;
  min-height: 0;
  min-width: 0;
  width: 100%;
}

.preview-toggle-button svg {
  width: 18px;
  height: 18px;
}

.preview-surface {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  min-width: 0;
  width: 100%;
  overflow: hidden;
}

.preview-editor {
  width: 100%;
  height: 100%;
  flex: 1;
  min-height: 0;
  padding: 16px;
  border-radius: 16px;
  border: 1px solid var(--md-question-border, var(--md-editor-border));
  background-color: var(--md-question-bg, var(--md-editor-bg));
  color: var(--preview-ink);
  font-family: var(--mono);
  font-size: 0.85rem;
  resize: none;
  caret-color: var(--md-editor-caret);
}

.preview.markdown.md-preview,
.preview.raw,
textarea.preview-editor {
  flex: 1;
  min-height: 0;
  min-width: 0;
  width: 100%;
  height: 100%;
  max-height: 100%;
  overflow: auto;
}

.preview.preview-editor.markdown {
  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.6;
  white-space: normal;
}

.preview.preview-editor.markdown a {
  cursor: text;
}

.preview.preview-editor.markdown img {
  pointer-events: none;
  -webkit-user-drag: none;
}

.preview-editor:hover {
  border-color: var(--md-editor-border-hover);
}

.preview-editor:focus-visible {
  outline: none;
  border-color: var(--md-editor-focus-border);
  box-shadow: 0 0 0 2px var(--md-editor-focus-glow);
}

.preview-editor::selection {
  background: var(--md-editor-selection-bg);
  color: var(--preview-ink);
}

:root[data-md-editor-grid="on"] .preview-editor,
:root[data-md-editor-grid="on"] .preview.markdown,
:root[data-md-editor-grid="on"] .preview.raw {
  background-image:
    radial-gradient(
      circle at 50% 50%,
      var(--md-grid-dot) 0,
      var(--md-grid-dot) var(--md-grid-dot-size),
      transparent calc(var(--md-grid-dot-size) + 0.5px)
    ),
    radial-gradient(
      ellipse var(--md-grid-line-size) calc(var(--md-grid-stroke) / 2)
        at 50% calc(50% - var(--md-grid-cross-offset)),
      var(--md-grid-line) 0,
      var(--md-grid-line) 100%,
      transparent 100%
    ),
    radial-gradient(
      ellipse var(--md-grid-line-size) calc(var(--md-grid-stroke) / 2)
        at 50% calc(50% + var(--md-grid-cross-offset)),
      var(--md-grid-line) 0,
      var(--md-grid-line) 100%,
      transparent 100%
    ),
    radial-gradient(
      ellipse calc(var(--md-grid-stroke) / 2) var(--md-grid-line-size)
        at calc(50% - var(--md-grid-cross-offset)) 50%,
      var(--md-grid-line) 0,
      var(--md-grid-line) 100%,
      transparent 100%
    ),
    radial-gradient(
      ellipse calc(var(--md-grid-stroke) / 2) var(--md-grid-line-size)
        at calc(50% + var(--md-grid-cross-offset)) 50%,
      var(--md-grid-line) 0,
      var(--md-grid-line) 100%,
      transparent 100%
    );
  background-size: var(--md-grid-size) var(--md-grid-size);
  background-position: 0 0;
  background-repeat: repeat;
  background-attachment: local;
}

.preview.markdown ::selection,
.preview.raw ::selection {
  background: var(--md-selection-bg);
  color: var(--preview-ink);
}

.preview.raw {
  font-family: var(--mono);
  font-size: 0.85rem;
  white-space: pre-wrap;
}

.preview.raw pre {
  margin: 0;
  white-space: pre-wrap;
  font-family: inherit;
  font-size: inherit;
}

.md-preview {
  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.6;
  white-space: normal;
}

.md-preview > :first-child {
  margin-top: 0;
}

.md-preview > :last-child {
  margin-bottom: 0;
}

.md-preview h1 {
  font-size: 1.4rem;
  margin: 0 0 0.6rem;
}

.md-preview h2 {
  font-size: 1.2rem;
  margin: 1.2rem 0 0.6rem;
}

.md-preview h3 {
  font-size: 1.05rem;
  margin: 1rem 0 0.5rem;
}

.md-preview h4 {
  font-size: 1rem;
  margin: 0.9rem 0 0.5rem;
}

.md-preview h5 {
  font-size: 0.95rem;
  margin: 0.8rem 0 0.45rem;
}

.md-preview h6 {
  font-size: 0.9rem;
  margin: 0.7rem 0 0.4rem;
}

.md-preview p {
  margin: 0 0 0.8rem;
}

.md-preview ul,
.md-preview ol {
  margin: 0 0 0.8rem;
  padding-left: 1.4rem;
}

.md-preview a {
  color: var(--md-link);
  text-decoration: underline;
}

.md-preview a:hover {
  color: var(--md-link-hover);
}

.md-preview code {
  font-family: var(--mono);
  font-size: 0.85rem;
  background: var(--preview-code-bg);
  border: 1px solid var(--preview-code-border);
  border-radius: 6px;
  padding: 2px 6px;
}

.md-preview pre {
  margin: 0 0 0.8rem;
  padding: 12px;
  background: var(--preview-code-bg);
  border: 1px solid var(--preview-code-border);
  border-radius: 12px;
  overflow-x: auto;
}

.md-preview pre code {
  background: transparent;
  border: none;
  padding: 0;
}

.md-preview blockquote {
  margin: 0 0 0.8rem;
  padding-left: 12px;
  border-left: 3px solid var(--md-blockquote-border);
  color: var(--preview-ink);
  opacity: 0.9;
}

.markdown-table {
  width: 100%;
  overflow-x: auto;
  margin: 0 0 0.8rem;
  border-radius: 12px;
  border: 1px solid var(--line-soft);
  background: var(--md-table-bg);
}

.md-preview table {
  width: max-content;
  min-width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.md-preview thead th {
  background: var(--md-table-head-bg);
  text-align: left;
  font-weight: 600;
}

.md-preview th,
.md-preview td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--line-soft);
  border-right: 1px solid var(--line-soft);
}

.md-preview tr > :last-child {
  border-right: none;
}

.md-preview tbody tr:last-child th,
.md-preview tbody tr:last-child td {
  border-bottom: none;
}

.preview.placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  flex: 1;
  min-height: 0;
  text-align: center;
  color: var(--muted);
  font-style: italic;
}

@media (max-width: 1199.98px) {
  .preview-panel,
  .preview-panel .preview-content,
  .preview-panel .preview-surface {
    min-width: 0;
    min-height: 0;
  }

  .preview-panel .preview-content,
  .preview-panel .preview-surface,
  .preview-panel .preview-editor,
  .preview-panel .preview,
  .preview-panel .preview.markdown.md-preview,
  .preview-panel .preview.raw,
  .preview-panel textarea.preview-editor {
    width: 100%;
    min-width: 0;
    height: 42rem;
    max-height: 42rem;
  }

  .preview-panel .preview-editor,
  .preview-panel .preview {
    flex: 1 1 100%;
  }

  .preview-panel .preview.markdown.md-preview,
  .preview-panel .preview.raw,
  .preview-panel .preview-editor,
  .preview-panel textarea.preview-editor {
    box-sizing: border-box;
  }

  .preview-panel textarea.preview-editor {
    display: block;
  }

  .preview-panel .preview.raw > pre {
    width: 100%;
    min-width: 0;
    box-sizing: border-box;
    overflow: auto;
  }
}

/*
 * @file apps/fmd-desktop/src/styles/components/responsive.css
 *
 * Zweck:
 * - Definiert Styles fuer responsive.
 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer responsive.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

@media (max-width: 1199.98px) {
  .flashcard-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
  }

  .exam-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
  }

  .fast-flashcard-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
    grid-template-areas: "fast-main fast-sidebar";
    grid-template-rows: auto;
  }

  .fast-session-grid {
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  }

  .fast-stats-blocks {
    grid-template-columns: 1fr;
  }

  .spaced-repetition-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
    grid-template-areas: "sr-main sr-sidebar";
    grid-template-rows: auto;
  }

  .fast-flashcard-main .fast-flashcard-panel {
    order: 1;
  }

  .fast-flashcard-main .fast-stats-panel {
    order: 2;
  }

  .spaced-repetition-main .sr-flashcards-panel {
    order: 1;
  }

  .spaced-repetition-main .sr-diagram-panel {
    order: 2;
  }

  .sr-stats-top {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 980px) {
  .flashcard-layout {
    grid-template-columns: 1fr;
  }

  .exam-layout {
    grid-template-columns: 1fr;
  }

  .fast-flashcard-layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      "fast-main"
      "fast-sidebar";
    grid-template-rows: auto auto;
  }

  .spaced-repetition-layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      "sr-main"
      "sr-sidebar";
    grid-template-rows: auto auto;
  }

  .flashcard-note-files-panel,
  .fast-note-files-panel,
  .sr-note-files-panel,
  .exam-files-panel {
    display: none;
  }

  .app-shell,
  .app-shell.sidebar-collapsed {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: fixed;
    inset: 0 auto 0 0;
    width: min(320px, 85vw);
    max-height: 100vh;
    overflow-y: auto;
    transform: translateX(-110%);
    transition: transform 0.2s ease;
    z-index: 30;
  }

  .app-shell.nav-open .sidebar {
    transform: translateX(0);
  }

  .app-shell.dashboard-active .content {
    overflow: auto;
  }

  .mobile-nav-header {
    display: flex;
  }

  .mobile-nav-close {
    display: inline-flex;
  }

  .app-shell.nav-open .mobile-nav-backdrop {
    opacity: 1;
    pointer-events: auto;
  }

  .dashboard-page {
    height: auto;
  }

  .workspace {
    grid-template-columns: 1fr;
    flex: 0 0 auto;
  }

  .workspace.note-collapsed {
    grid-template-columns: 1fr;
  }

  .workspace .note-column {
    order: -1;
  }

  .workspace .panel,
  .workspace .vault-details {
    height: auto;
  }

  .sidebar {
    order: 1;
  }

  .content {
    order: 2;
  }
}

/*
 * @file apps/fmd-desktop/src/styles/components/settings.css
 *
 * Zweck:
 * - Definiert Styles fuer settings.
 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer settings.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

.settings-layout {
  display: grid;
  grid-template-columns: minmax(200px, 240px) minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}

.settings-nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 14px;
  border-radius: 18px;
  border: 1px solid var(--line-soft);
  background: var(--panel);
  box-shadow: var(--shadow-soft);
  min-width: 0;
}

.settings-nav-divider {
  padding: 8px 6px 4px;
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.settings-nav-divider:not(:first-child) {
  margin-top: 8px;
}

.settings-nav-item {
  width: 100%;
  display: grid;
  grid-template-columns: 18px 1fr;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease;
}

.settings-nav-item:hover {
  background: var(--field-bg);
  border-color: var(--line-soft);
}

.settings-nav-item.active {
  background: var(--accent-weak-bg);
  border-color: var(--accent-weak-border);
  color: var(--accent-strong);
}

.settings-nav-item:focus-visible {
  outline: 2px solid var(--accent-focus-ring);
  outline-offset: 2px;
}

.settings-nav-icon {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
}

.settings-nav-item.active .settings-nav-icon {
  color: var(--accent-strong);
}

.settings-nav-icon svg {
  width: 100%;
  height: 100%;
}

.settings-nav-label {
  font-weight: 600;
}

.settings-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.settings-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line-soft);
}

.settings-panel-title {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.settings-panel-title-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.settings-panel-title-text h2 {
  margin: 0;
}

.settings-panel-icon {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: var(--accent-weak-bg);
  color: var(--accent-strong);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.settings-panel-icon svg {
  width: 20px;
  height: 20px;
}

.settings-panel-body {
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-width: 0;
}

.settings-page {
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-width: 0;
}

.settings-page .panel {
  min-width: 0;
}

.settings-single-column {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.settings-app-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  align-items: start;
}

.settings-app-grid .vault-index-panel {
  grid-column: 1;
}

.settings-app-grid .settings-performance-panel {
  grid-column: 2;
}

.settings-review-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  align-items: stretch;
}

.settings-review-grid .panel {
  height: 100%;
}

.settings-review-grid .exam-settings-panel {
  grid-column: 1 / -1;
}


.exam-settings-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 0.8fr);
  gap: 20px;
  align-items: start;
}

.exam-settings-panel .panel-body,
.exam-settings-toggles-panel .panel-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.exam-settings-toggles-panel .setting-row:first-of-type {
  border-top: none;
  padding-top: 0;
}

.exam-settings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
  align-items: center;
}

.exam-settings-panel .exam-compact-input {
  height: 36px;
  padding: 4px 12px;
  font-size: 0.9rem;
  line-height: 1.1;
}

.exam-time-input {
  display: flex;
  align-items: center;
  gap: 8px;
}

.exam-points-table {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(88px, 1fr));
  gap: 4px 4px;
  max-height: 220px;
  overflow: auto;
  padding-right: 6px;
}

.exam-points-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.exam-points-row .text-input {
  width: 90px;
}

.exam-settings-panel .exam-points-row {
  justify-content: flex-start;
  gap: 2px;
  padding: 2px;
}

.exam-settings-panel .exam-points-row .label {
  min-width: 6px;
  text-align: right;
}

.exam-settings-panel .exam-points-row .exam-compact-input {
  width: 70px;
  min-width: 80px;
  height: 32px;
  padding: 0 6px;
  font-size: 0.9rem;
  line-height: 0;
}

.exam-settings-summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.exam-settings-summary .muted {
  font-size: 0.78rem;
  line-height: 1.2;
}

.exam-settings-actions {
  display: flex;
  align-items: center;
}

.settings-tab-content {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.settings-tab-header {
  flex-wrap: wrap;
  align-items: flex-start;
}

.settings-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.settings-tab-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

@media (max-width: 1199.98px) {
  .settings-layout {
    grid-template-columns: 1fr;
  }

  .settings-app-grid {
    grid-template-columns: 1fr;
  }

  .settings-app-grid .vault-index-panel,
  .settings-app-grid .settings-performance-panel {
    grid-column: 1;
  }

  .exam-settings-layout {
    grid-template-columns: 1fr;
  }
}

.setting-row {
