  flex-direction: column;
  gap: 6px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.settings-flashcards-panel .setting-row:first-of-type,
.fast-flashcard-tools-panel .setting-row:first-of-type,
.spaced-repetition-panel .setting-row:first-of-type {
  border-top: none;
  padding-top: 0;
}


.setting-subrow {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}

.spaced-repetition-layout .setting-row {
  border-top: none;
  padding-top: 0;
}

.setting-inline {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.setting-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.status-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.status-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.status-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.status-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 600;
}

.status-checkbox input {
  accent-color: var(--accent);
}

.appearance-panel .setting-row:first-of-type {
  border-top: none;
  padding-top: 0;
}

.editor-settings-block .setting-row:first-of-type {
  border-top: none;
  padding-top: 0;
}

.editor-settings-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.editor-settings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.editor-settings-block {
  border: 1px solid var(--line-soft);
  border-radius: 16px;
  padding: 14px;
  background: var(--panel);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.editor-settings-block h3 {
