  flex-direction: column;
  gap: 12px;
}

.shortcut-row {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
}

.shortcut-row.is-conflict {
