  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: default;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.shortcut-chip:focus-visible {
  outline: 2px solid var(--accent-focus-ring);
  outline-offset: 2px;
}

.shortcut-capture {
  font-size: 0.75rem;
  color: var(--muted);
}

.shortcut-info {
  position: relative;
  display: inline-flex;
}

.shortcut-info-button {
  width: 24px;
  height: 24px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--muted);
  font-size: 0.75rem;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.shortcut-info-button:hover {
  border-color: var(--accent-border);
  color: var(--accent-strong);
}

.shortcut-info-button:focus-visible {
  outline: 2px solid var(--accent-focus-ring);
  outline-offset: 2px;
}

.shortcut-info-popover {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  width: min(360px, 80vw);
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--panel);
  box-shadow: var(--shadow-soft);
  color: var(--ink);
  z-index: 5;
}

.shortcut-info-popover p {
  margin: 0;
}

.shortcut-info-popover p + p {
  margin-top: 6px;
}

.shortcut-conflict-detail {
  font-size: 0.8rem;
  color: var(--error-ink);
}

@media (max-width: 960px) {
  .shortcut-row-top {
    flex-wrap: wrap;
  }

  .shortcut-row-meta {
    grid-template-columns: 1fr;
    justify-items: flex-start;
  }

  .shortcut-binding {
    align-items: flex-start;
    justify-self: start;
  }
}

.appearance-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 320px);
  gap: 20px;
  align-items: start;
}

.appearance-main {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.appearance-editor-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border-radius: 16px;
  border: 1px solid var(--accent-weak-border);
  background: var(--accent-weak-bg);
}

.appearance-editor-header h3 {
  margin: 0;
  font-size: 1rem;
}

.appearance-editor-inline {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.appearance-grid-intensity {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.appearance-grid-intensity .pill-grid {
  gap: 6px;
}

@media (max-width: 960px) {
  .appearance-layout {
    grid-template-columns: 1fr;
  }
}

.theme-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
}

.toggle-label {
  font-size: 0.85rem;
  color: var(--muted);
}

.switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 46px;
  height: 26px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: relative;
  width: 100%;
  height: 100%;
  background: var(--line);
  border-radius: 999px;
  transition: background 0.2s ease;
}

.slider::before {
  content: "";
  position: absolute;
  width: 20px;
  height: 20px;
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: var(--shadow-soft);
  transition: transform 0.2s ease;
}

.switch input:checked + .slider {
  background: var(--accent);
}

.switch input:checked + .slider::before {
  transform: translateX(20px);
}

.switch input:disabled + .slider {
  background: var(--line-soft);
  opacity: 0.6;
  cursor: not-allowed;
}

.text-input {
  min-width: 140px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--field-border);
  background: var(--field-bg);
  color: var(--ink);
  font-size: 0.85rem;
}

.text-input:focus-visible {
  outline: none;
  border-color: var(--accent-border);
  box-shadow: 0 0 0 2px var(--field-glow);
}

.text-input:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.accent-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.color-wheel {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  border: 1px solid var(--field-border);
  background: var(--field-bg);
  padding: 0;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
}

.color-wheel::-webkit-color-swatch-wrapper {
  padding: 0;
}

.color-wheel::-webkit-color-swatch {
  border: none;
  border-radius: 10px;
}

.color-wheel::-moz-color-swatch {
  border: none;
  border-radius: 10px;
}

.accent-palette {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.accent-swatch {
  width: 26px;
  height: 26px;
  border-radius: 9px;
  border: 2px solid transparent;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px var(--line-soft);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.accent-swatch:hover {
  transform: translateY(-1px);
}

.accent-swatch.active {
  box-shadow:
    inset 0 0 0 1px var(--line-soft),
    0 0 0 2px var(--panel),
    0 0 0 4px var(--accent-border);
}

.accent-hex {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.markdown-accent-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.markdown-accent-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.markdown-accent-preview {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  border: 1px solid var(--line-soft);
  box-shadow: inset 0 0 0 1px var(--line-soft);
}

.markdown-accent-trigger {
  padding: 0;
  cursor: pointer;
  background: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.markdown-accent-trigger:hover {
  transform: translateY(-1px);
  box-shadow:
    inset 0 0 0 1px var(--line-soft),
    0 0 0 2px var(--accent-weak-border);
}

.markdown-accent-trigger:focus-visible {
  outline: 2px solid var(--accent-focus-ring);
  outline-offset: 2px;
}

.markdown-accent-picker {
  margin-top: 8px;
  padding: 10px;
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  background: var(--panel);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.markdown-accent-grid {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 6px;
}

.markdown-accent-swatch {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  border: 1px solid transparent;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px var(--line-soft);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.markdown-accent-swatch:hover {
  transform: translateY(-1px);
}

.markdown-accent-swatch.active {
  box-shadow:
    inset 0 0 0 1px var(--line-soft),
    0 0 0 2px var(--panel),
    0 0 0 4px var(--accent-border);
}

.markdown-accent-custom {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.markdown-accent-custom-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.markdown-accent-custom-swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 22px;
}

.hub-modal-panel.markdown-accent-modal {
  width: min(560px, 92vw);
  max-height: min(72vh, 620px);
}

.markdown-accent-modal-body .markdown-accent-picker {
  margin-top: 0;
  padding: 0;
  border: none;
  background: transparent;
}

.hex-input {
  min-width: 120px;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--field-border);
  background: var(--field-bg);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.85rem;
}

.helper-text {
  font-size: 0.8rem;
  color: var(--muted);
}

.helper-text.error-text {
  color: var(--accent-strong);
}

.path-value {
  word-break: break-all;
  overflow-wrap: anywhere;
}

.pill-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pill {
  padding: 6px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong);
  font-size: 0.85rem;
  font-weight: 600;
}

.settings-focus-highlight {
  outline: 2px solid var(--accent-highlight);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-highlight) 35%, transparent);
  transition: box-shadow 0.3s ease;
}

/*
 * @file apps/fmd-desktop/src/styles/components/spaced-repetition.css
 *
 * Zweck:
 * - Definiert Styles fuer spaced repetition.
 *
 * Verantwortlichkeiten:
 * - Layout- und Komponenten-Styles fuer spaced repetition.
 * - Zustands- und Variantenklassen fuer Interaktionen.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
