 */

.stats-panel .panel-body {
  min-height: auto;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.kpi-card {
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--block-bg);
  border: 1px solid var(--block-border);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.kpi-label {
  color: var(--muted);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.kpi-value {
  font-weight: 700;
  font-size: 1.2rem;
}

.chart-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  border-radius: 16px;
  background: var(--block-bg);
  border: 1px solid var(--block-border);
}

.chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.chart-meta {
  font-size: 0.75rem;
  color: var(--muted);
}

.chart-canvas {
  padding: 10px;
  border-radius: 12px;
  background: var(--panel);
  border: 1px solid var(--line-soft);
}

.sr-chart {
  width: 100%;
  height: 120px;
}

.sr-chart-axis {
  stroke: var(--line);
  stroke-width: 0.8;
}

.sr-chart-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2;
}

.chart-axis {
  display: flex;
  justify-content: space-between;
  font-size: 0.7rem;
  color: var(--muted);
}

.stats-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.fast-stats-switch {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.fast-panel-header-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fast-panel-title {
  margin: 0;
}

.fast-stats-toggle {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.fast-panel-collapse {
  border: none;
  background: transparent;
  color: inherit;
  padding: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.fast-panel-collapse:focus-visible {
  outline: 2px solid var(--accent-focus-ring);
  outline-offset: 2px;
  border-radius: 12px;
}

.fast-panel-collapse:hover .panel-header-chevron {
  color: var(--accent-strong);
}

.fast-stats-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
}


.fast-stats-blocks {
  display: grid;
  grid-template-columns: minmax(0, 0.6fr) minmax(0, 1fr);
  gap: 12px;
}

.fast-time-block,
.fast-stats-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 16px;
  background: var(--block-bg);
  border: 1px solid var(--block-border);
}

.fast-time-block--compact {
  padding: 8px 10px;
}

.fast-time-block--hidden {
  display: none;
}

.fast-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.fast-stats-block-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.fast-stats-grid {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}

.fast-stats-grid .stats-chart {
