  flex-direction: column;
  gap: 8px;
}

.fast-session-row {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) repeat(3, minmax(0, 0.7fr));
  gap: 8px;
  align-items: center;
  font-size: 0.85rem;
}

.fast-session-row.header {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.fast-session-cell {
  text-align: right;
}

.fast-session-cell.timestamp {
  text-align: left;
}

.stats-counters {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stats-counter {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.stats-label {
