  font-size: 0.85rem;
}

.stats-value {
  font-weight: 700;
  font-size: 1.1rem;
}

.stats-chart {
  --stats-primary: var(--accent);
  --stats-secondary: var(--error-ink);
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: conic-gradient(
    var(--stats-primary) 0 var(--correct-percent),
    var(--stats-secondary) var(--correct-percent) 100%
  );
  position: relative;
  flex-shrink: 0;
}

.stats-chart::after {
  content: "";
  position: absolute;
  inset: 10px;
