/*
 * @file apps/fmd-desktop/src/styles/layout.css
 *
 * Zweck:
 * - Definiert Layout- und Shell-Styles fuer die App.
 *
 * Verantwortlichkeiten:
 * - Layout-, Grid- und Shell-Regeln fuer die App-Struktur.
 * - Basis fuer Sidebar-, Content- und Panel-Anordnung.
 *
 * Verbunden mit:
 * - apps/fmd-desktop/src/App.css: Nutzt dieses Modul.
 * - apps/fmd-desktop/src/styles/tokens.css: Design-Tokens und Variablen.
 *
 * Hinweise:
 * - Nutzt CSS-Variablen aus styles/tokens.css fuer konsistente Farben und Abstaende.
 */

.app-shell {
  --sidebar-width: 260px;
  --sidebar-collapsed-width: 36px;
  position: relative;
  display: grid;
  grid-template-columns: var(--sidebar-width) 1fr;
  grid-template-rows: minmax(0, 1fr);
  gap: 24px;
  padding: 24px;
  min-height: 100vh;
  height: 100vh;
  animation: riseIn 0.6s ease both;
  transition: grid-template-columns 0.2s ease;
}

.app-shell.sidebar-collapsed {
  --sidebar-width: var(--sidebar-collapsed-width);
}

.app-shell.layout-table,
.app-shell.layout-table.sidebar-collapsed {
  grid-template-columns: 1fr;
}

.app-shell.compact-top-nav {
  grid-template-rows: auto minmax(0, 1fr);
}

.app-shell.compact-top-nav .study-section-nav {
  grid-column: 1 / -1;
  grid-row: 1;
}

.app-shell.compact-top-nav .sidebar,
.app-shell.compact-top-nav .content {
  grid-row: 2;
}

.app-shell.layout-table .sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: min(320px, 85vw);
  max-height: 100vh;
  overflow-y: auto;
  transform: translateX(-110%);
  transition: transform 0.2s ease;
  z-index: 30;
}

.app-shell.layout-table.nav-open .sidebar {
  transform: translateX(0);
}

.app-shell.dashboard-active {
  height: 100vh;
  grid-template-rows: minmax(0, 1fr);
}

.app-shell.compact-top-nav.dashboard-active {
  grid-template-rows: auto minmax(0, 1fr);
}

.app-shell.dashboard-active .content {
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.app-shell::before {
  content: "";
  position: absolute;
  inset: 32px 40px auto auto;
  width: 240px;
  height: 240px;
  background: var(--glow);
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
}

.app-shell > * {
  position: relative;
  z-index: 1;
}

.sidebar {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: var(--left-bg-tint);
  border-radius: 24px;
  padding: 24px;
  box-shadow: var(--shadow);
  border: 1px solid var(--line-soft);
  transition: padding 0.2s ease;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.sidebar.collapsed {
  padding: 8px 6px;
  gap: 0;
  align-items: stretch;
  justify-content: flex-start;
}

.sidebar-handle {
  position: absolute;
  inset: 0 auto 0 0;
  width: 16px;
  border: none;
  padding: 0;
  margin: 0;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  border-radius: 24px 0 0 24px;
  transition: background 0.2s ease, color 0.2s ease;
  display: grid;
  place-items: center;
